// Act Natural!: The Oxford Method, Book 6 (B2). One conversation for each unit of the book,
// made from the unit's model questions and answers (the vocabulary and structures of the unit).
// The tasks are in Spanish, so they don't give away the English words: the student has to find them.
// The situations are invented, as in the other books.
//
// Same format as book5.js: each unit has the two roles of the game.
//   turns + end   the other person speaks first and the student answers (same format as T in scenes.js)
//   staff + bye   the student starts and says the other person's lines (same format as W in staff.js),
//                 and the other person answers with the model answers.

const BOOK6 = [];
function UNIT6(o){
  BOOK6.push({ id: "b6u" + o.unit, unit: o.unit, book: true, label: "Book 6", name: o.name, icon: o.icon, who: o.who, face: o.face,
    color: BOOK_COLORS[(o.unit - 1) % BOOK_COLORS.length], leave: o.leave || "Sorry, I have to go now. Bye!",
    levels: { B2: { turns: o.turns, end: o.end } } });
  STAFF["b6u" + o.unit] = { client: o.client, face: o.cface, leave: o.cleave || "Never mind. I'll ask someone else.",
    bye: { B2: o.bye }, B2: o.staff };
}

/* ===================== MODULE 1 ===================== */
UNIT6({ unit: 1, name: "Is it likely?", icon: "👨‍👩‍👧", who: "Cousin", face: "🧑", client: "Aunt", cface: "👩",
  turns: [
    T("Hi! Are you anxious about the family reunion on Sunday?", "Di que sí, un poco ansioso por la reunión.", "Yes, I'm a little anxious about it.|Yes, I'm a bit anxious about it.", "yes ; anxious ; little/bit",
      "Yes, I'm a little anxiety about it. :: 'Anxious' is the adjective; 'anxiety' is the noun.", "Yes, I'm a little anxious for it. :: We say anxious ABOUT something."),
    T("Why? Is it because of your in-laws?", "Di que sí: es relativamente difícil tener buena relación con ellos porque intentan influir en tus decisiones.", "Yes. It's relatively difficult to have a good relationship with them because they try to influence my decisions.|Yes. It's relatively difficult to have a good relationship with my in-laws because they try to influence my decisions.", "relatively ; difficult ; relationship ; influence ; decisions",
      "Yes. It's relative difficult to have a good relationship with them because they try to influence my decisions. :: Use the adverb: relatively difficult.", "Yes. It's relatively difficult to have a good relationship with them because they try to influence to my decisions. :: 'Influence' has a direct object: influence my decisions."),
    T("I see. Do you think stress is related to health problems?", "Responde que sí: un ataque al corazón puede estar relacionado con el estrés.", "Yes, a heart attack can be related to stress.|Yes, I think a heart attack can be related to stress.", "yes ; heart attack ; related ; stress",
      "Yes, a heart attack can be relate to stress. :: After 'be' use the past participle: related.", "Yes, a heart attack can be related with stress. :: We say related TO."),
    T("True. Anyway, how likely is it that you'll come on Sunday?", "Di que es bastante probable que vayas, pero que no estás seguro.", "It's quite likely that I'll come, but I'm not sure.|It's very likely that I'll come, but I'm not sure.", "likely ; come ; not sure",
      "It's quite probably that I'll come, but I'm not sure. :: After 'It's quite' use the adjective: likely.", "It's quite likely that I come, but I'm not sure. :: For the future use 'will': that I'll come."),
  ], end: "Great. See you on Sunday!",
  staff: [
    W("Pregunta a tu tía si está ansiosa por la reunión familiar del domingo.", "Are you anxious about the family reunion on Sunday?|Are you a little anxious about the family reunion on Sunday?", "anxious ; reunion ; sunday",
      "Are you anxiety about the family reunion on Sunday? :: 'Anxious' is the adjective; 'anxiety' is the noun.", "Are you anxious for the family reunion on Sunday? :: We say anxious ABOUT something.", "q"),
    W("Pregunta si es por culpa de sus suegros.", "Is it because of your in-laws?|Is it because of your in-laws, perhaps?", "because ; in-laws",
      "Is because of your in-laws? :: A question needs 'it': Is it because…?", "Is it because for your in-laws? :: We say 'because OF'.", "q"),
    W("Di que es relativamente difícil tener buena relación con ellos porque intentan influir en tus decisiones.", "It's relatively difficult to have a good relationship with them because they try to influence my decisions.|It's relatively difficult to have a good relationship with in-laws because they try to influence my decisions.", "relatively ; difficult ; relationship ; influence ; decisions",
      "It's relative difficult to have a good relationship with them because they try to influence my decisions. :: Use the adverb: relatively difficult.", "It's relatively difficult to have a good relation with them because they try to influence my decisions. :: The word is 'relationship'."),
    W("Pregunta si cree que el estrés está relacionado con los problemas de salud.", "Do you think stress is related to health problems?|Do you think that stress is related to health problems?", "think ; stress ; related ; health",
      "Do you think stress is relate to health problems? :: After 'is' use the past participle: related.", "Do you think stress is related with health problems? :: We say related TO.", "q"),
    W("Pregunta cómo de probable es que venga el domingo.", "How likely is it that you'll come on Sunday?|How likely is it that you will come on Sunday?", "how ; likely ; come ; sunday",
      "How is likely that you come on Sunday? :: Question order: How likely is it…?", "How likely it is that you'll come on Sunday? :: Question order: How likely is it…?", "q"),
  ], bye: "Of course. Bye! See you on Sunday." });

UNIT6({ unit: 2, name: "What's it made out of?", icon: "🍰", who: "Baker", face: "🧑‍🍳", client: "Friend", cface: "🧔",
  turns: [
    T("Hi! What's your favourite cake made out of?", "Di que tu tarta favorita está hecha de harina, agua, levadura y azúcar glas.", "My favourite cake is made out of flour, water, yeast and icing sugar.|My favourite cake's made out of flour, water, yeast and sugar.", "favourite/favorite ; made ; out of ; flour",
      "My favourite cake is make out of flour, water, yeast and icing sugar. :: Passive: is made.", "My favourite cake is made with of flour, water, yeast and icing sugar. :: For a mixture we say 'made out of'."),
    T("Sounds good. And what's wine made from?", "Di que el vino se hace de uvas y pregunta cómo se hace el yogur.", "Wine is made from grapes. How's yoghurt made?|Wine's made from grapes. How is yoghurt made?", "wine ; grapes ; how/hows ; yoghurt/yogurt",
      "Wine is made by grapes. How's yoghurt made? :: A material uses 'made from': made from grapes.", "Wine is made from grapes. How yoghurt is made? :: Question order: How is yoghurt made?", "q"),
    T("By adding bacteria to milk, I think. By the way, what ingredients do you use to add flavour to a dish?", "Di que usas ingredientes como sal y pimienta para dar sabor a un plato.", "I use such ingredients as salt and pepper to add flavour to a dish.|I use salt and pepper to add flavour to a dish.", "salt ; pepper ; flavour/flavor ; dish",
      "I use salt and pepper for add flavour to a dish. :: Purpose: to add (not 'for add').", "I use salt and pepper to add flavour of a dish. :: We add flavour TO a dish."),
    T("Nice. And in what proportions do you mix the ingredients for a strawberry milkshake?", "Di que mezclas tres partes de yogur por dos de fresas.", "I mix three parts of yoghurt to two parts of strawberries.|You mix three parts of yoghurt to two parts of strawberries.", "three ; parts ; yoghurt/yogurt ; two ; strawberries",
      "I mix three part of yoghurt to two part of strawberries. :: Plural: three parts, two parts.", "I mix three parts of yoghurt and two parts from strawberries. :: Two parts OF strawberries."),
  ], end: "Delicious! Send me the recipe.",
  staff: [
    W("Pregunta de qué está hecha su tarta favorita.", "What's your favourite cake made out of?|What is your favourite cake made out of?", "favourite/favorite ; cake ; made ; out of",
      "What your favourite cake is made out of? :: Question order: What's your favourite cake made out of?", "What's your favourite cake made out? :: Don't forget 'of': made out of.", "q"),
    W("Di que tu tarta favorita está hecha de harina, agua, levadura y azúcar glas.", "My favourite cake is made out of flour, water, yeast and icing sugar.|My favourite cake's made out of flour, water, yeast and sugar.", "made ; out of ; flour ; water ; yeast",
      "My favourite cake is make out of flour, water, yeast and icing sugar. :: Passive: is made.", "My favourite cake is made with of flour, water, yeast and icing sugar. :: For a mixture we say 'made out of'."),
    W("Pregunta de qué se hace el vino.", "What's wine made from?|What is wine made from?", "wine ; made ; from",
      "What wine is made from? :: Question order: What is wine made from?", "What's wine made by? :: A material uses 'made from'.", "q"),
    W("Pregunta qué ingredientes usa para dar sabor a un plato.", "What ingredients do you use to add flavour to a dish?|What ingredients do you use to add flavor to a dish?", "ingredients ; add ; flavour/flavor ; dish",
      "What ingredients you use to add flavour to a dish? :: Questions need 'do': What ingredients do you use…?", "What ingredients do you use for add flavour to a dish? :: Purpose: to add.", "q"),
    W("Pregunta en qué proporciones mezcla los ingredientes para un batido de fresa.", "In what proportions do you mix the ingredients to get a strawberry milkshake?|In what proportions do you mix the ingredients for a strawberry milkshake?", "proportions ; mix ; strawberry ; milkshake/shake",
      "In what proportion you mix the ingredients to get a strawberry milkshake? :: Questions need 'do' and the plural: proportions.", "In what proportions do you mix the ingredients to get a milkshake of strawberry? :: Say 'a strawberry milkshake'.", "q"),
  ], bye: "Thanks for the tips. Bye!" });

UNIT6({ unit: 3, name: "Just in case", icon: "🔑", who: "Neighbour", face: "🧑", client: "Friend", cface: "👩",
  turns: [
    T("Hi! Why is it better to wear bright colours on a hot day?", "Di que los colores claros no absorben tanto calor.", "Because bright colours don't absorb so much heat.|Bright colours don't absorb so much heat.", "bright ; absorb ; heat",
      "Because bright colours not absorb so much heat. :: Negative present: don't absorb.", "Because bright colours don't absorb so many heat. :: 'Heat' is uncountable: so much heat."),
    T("Of course. By the way, there was a robbery near here. Have any flats been robbed in your neighbourhood recently?", "Di que sí, algunos pisos han sido robados recientemente.", "Yes, some flats have recently been robbed in my neighbourhood.|Yes, some flats have been robbed recently.", "yes ; flats ; robbed ; recently",
      "Yes, some flats have been rob recently. :: Passive: have been robbed.", "Yes, some flats are robbed recently. :: Present perfect passive: have been robbed."),
    T("How awful. Do you have spare keys, in case you lose the original one?", "Di que sí, tienes llaves de repuesto por si pierdes la original.", "Yes, I have spare keys in case I lose the original one.|Yes, I do. I have spare keys in case I lose the original.", "spare ; keys ; in case ; lose",
      "Yes, I have spare keys in case I will lose the original one. :: After 'in case' use the present: in case I lose.", "Yes, I have spare keys in case of I lose the original one. :: 'In case' + a clause (no 'of')."),
    T("Good idea. Sorry to interrupt, but are you driving to the party tonight?", "Di que no pasa nada y ofrece llevarle en coche: pasarás por su casa de todos modos.", "Don't worry, I'll give you a lift as I'll be driving past your house in any case.|No problem. I'll give you a lift. I'll be driving past your house in any case.", "lift ; driving ; house ; in any case",
      "Don't worry, I give you a lift as I'll be driving past your house in any case. :: An offer uses 'will': I'll give you a lift.", "Don't worry, I'll give you a lift as I'll be driving past your house in any cases. :: 'In any case' is singular."),
  ], end: "Thanks a lot!",
  staff: [
    W("Pregunta por qué es mejor llevar colores claros en un día de calor.", "Why is it better to wear bright colours on a hot day?|Why is it better to wear bright colours when it's hot?", "why ; better ; bright ; hot",
      "Why it is better to wear bright colours on a hot day? :: Question order: Why is it better…?", "Why is better to wear bright colours on a hot day? :: You need 'it': Why is it better…?", "q"),
    W("Pregunta si han robado algún piso recientemente en su barrio.", "Have any flats recently been robbed in your neighbourhood?|Have any flats been robbed in your neighbourhood recently?", "flats ; robbed ; neighbourhood/neighborhood",
      "Have any flats recently been rob in your neighbourhood? :: Passive: been robbed.", "Are any flats robbed recently in your neighbourhood? :: Present perfect passive: Have any flats been robbed…?", "q"),
    W("Pregunta si tiene llaves de repuesto por si pierde la original.", "Do you have spare keys in case you lose the original one?|Do you have spare keys in case you lose the original?", "spare ; keys ; in case ; lose",
      "Do you have spare keys in case you will lose the original one? :: After 'in case' use the present: in case you lose.", "Do you have spare keys in case of you lose the original one? :: 'In case' + a clause (no 'of').", "q"),
    W("Pide perdón por interrumpir y pregunta si va en coche a la fiesta esta noche.", "Sorry to interrupt, but are you driving to the party tonight?|Sorry to interrupt. Are you driving to the party tonight?", "interrupt ; driving ; party",
      "Sorry for interrupt, but are you driving to the party tonight? :: After 'sorry to' use the base verb: Sorry to interrupt.", "Sorry to disturb, but you are driving to the party tonight? :: Use 'interrupt' for stopping what someone is saying, and a question: are you driving…?", "q"),
    W("Ofrece llevarle en coche: pasarás por su casa de todos modos.", "I'll give you a lift as I'll be driving past your house in any case.|I'll give you a lift. I'll be driving past your house in any case.", "lift ; driving ; house ; in any case",
      "I give you a lift as I'll be driving past your house in any case. :: An offer uses 'will': I'll give you a lift.", "I'll give you a lift as I'll be driving past your house in any cases. :: 'In any case' is singular."),
  ], bye: "Thank you! See you later." });

UNIT6({ unit: 4, name: "Has it been delivered?", icon: "📦", who: "Receptionist", face: "💁", client: "Guest", cface: "🧑",
  turns: [
    T("Good morning! How can I help you?", "Di que reservaste una habitación y pregunta si pueden confirmarla por email.", "I booked a room. Could you confirm it by email, please?|I've booked a room. Can you confirm it by email, please?", "booked/book ; room ; confirm ; email",
      "I booked a room. Could you confirmation it by email, please? :: 'Confirm' is the verb; 'confirmation' is the noun.", "I booked a room. Could you confirm it for email, please? :: We say BY email.", "p"),
    T("Of course. You'll get a confirmation in a few minutes. Anything else?", "Pregunta si ha llegado un paquete urgente para ti.", "Has an urgent parcel been delivered for me?|Has an urgent parcel arrived for me?", "urgent ; parcel ; delivered/arrived",
      "Has an urgent parcel been deliver for me? :: Passive: been delivered.", "Has been delivered an urgent parcel for me? :: Question order: Has an urgent parcel been delivered…?", "q"),
    T("Yes, it came this morning. Can you sign here to prove it's been delivered?", "Di que claro y pregunta dónde puedes leer las últimas noticias en el hotel.", "Sure. Where can I look for the latest news in the hotel?|Of course. Where can I find the latest news here?", "latest ; news",
      "Sure. Where can I look for the last news in the hotel? :: For the newest news we say 'the latest news'.", "Sure. Where I can look for the latest news? :: Question order: Where can I…?", "q"),
    T("There are newspapers in the lounge. Are you here on business?", "Di que sí: vas a invitar a unos clientes (entertain) y das por hecho (assume) que el restaurante del hotel es bueno.", "Yes. I'm entertaining some customers, and I assume the hotel restaurant is good.|Yes, I'm entertaining customers. I assume the restaurant here is good.", "entertain ; customers/clients ; assume",
      "Yes. I'm entertainment some customers, and I assume the hotel restaurant is good. :: The verb is 'entertain': I'm entertaining.", "Yes. I'm entertaining some customers, and I assume that the hotel restaurant is a good. :: 'Good' is an adjective: no 'a'."),
  ], end: "It's excellent. Enjoy your stay!",
  staff: [
    W("Saluda y pregunta en qué puedes ayudarle.", "Good morning! How can I help you?|Good morning! What can I do for you?", "help/do",
      "Good morning! How can I helping you? :: After 'can' use the base verb: help.", "Good morning! How I can help you? :: Question order: How can I help you?", "q"),
    W("Di que recibirá una confirmación en unos minutos y pregunta si necesita algo más.", "You'll get a confirmation in a few minutes. Anything else?|You'll receive a confirmation in a few minutes. Anything else?", "confirmation ; minutes ; else",
      "You'll get a confirm in a few minutes. Anything else? :: The noun is 'confirmation'.", "You'll get a confirmation in a few minute. Anything else? :: Plural: a few minutes."),
    W("Di que el paquete llegó esta mañana y pídele que firme para demostrar que se ha entregado.", "Yes, it came this morning. Can you sign here to prove it's been delivered?|It arrived this morning. Could you sign here to prove it's been delivered?", "morning ; sign ; prove ; delivered",
      "It came this morning. Can you sign here for prove it's been delivered? :: Purpose: to prove.", "It came this morning. Can you sign here to prove it's been deliver? :: Passive: been delivered.", "p"),
    W("Pregunta si está aquí por negocios.", "Are you here on business?|Are you staying here on business?", "here ; business",
      "Are you here for business? :: We say ON business.", "You are here on business? :: Question order: Are you here…?", "q"),
    W("Di que el restaurante es excelente y desea una buena estancia.", "It's excellent. Enjoy your stay!|It's excellent. I hope you enjoy your stay.", "excellent ; enjoy ; stay",
      "It's excellent. Enjoy your staying! :: We say 'enjoy your stay'.", "It's excellent. Enjoy with your stay! :: 'Enjoy' takes no preposition."),
  ], bye: "Thank you very much!" });

UNIT6({ unit: 5, name: "Let's negotiate", icon: "🤝", who: "Car dealer", face: "🧔", client: "Customer", cface: "👩",
  turns: [
    T("Hello! Are you looking for a new car?", "Di que no: buscas un coche de segunda mano, pero sabes que es arriesgado.", "No, I'm looking for a second-hand car, but I know it's risky.|No, a second-hand one. But I know it's risky.", "second-hand/second hand ; risky",
      "No, I'm looking for a second hand's car, but I know it's risky. :: Say 'a second-hand car'.", "No, I'm looking for a second-hand car, but I know it's risk. :: Use the adjective: risky."),
    T("Don't worry. This one is in perfect condition. The tyres aren't worn out.", "Pregunta si se puede negociar el precio.", "Can we negotiate the price?|Is the price a matter for negotiation?", "negotiate/negotiation ; price",
      "Can we negotiation the price? :: 'Negotiate' is the verb; 'negotiation' is the noun.", "Is negotiable the price? :: Question order: Is the price negotiable?", "q"),
    T("Well, maybe a little. What's your offer?", "Di que has venido armado con argumentos y datos: ofreces tres mil libras.", "I've come armed with arguments and facts. I'm offering three thousand pounds.|I'm armed with facts. I offer three thousand pounds.", "armed ; facts/arguments ; thousand",
      "I've come armed of arguments and facts. I'm offering three thousand pounds. :: We say armed WITH arguments.", "I've come armed with arguments and facts. I'm offering three thousands pounds. :: After a number: three thousand (no s)."),
    T("Three thousand? That's not much. Can you give me a neat explanation?", "Explica que el coche es viejo y que los otros vendedores piden menos.", "The car is old, and the other dealers are asking for less.|It's an old car, and other dealers ask for less.", "old ; dealers ; less",
      "The car is old, and the other dealers are asking for fewer. :: With money (uncountable) we say 'less'.", "The car is old, and the others dealers are asking for less. :: As an adjective 'other' has no 's': the other dealers."),
  ], end: "All right. Three thousand two hundred, and it's yours.",
  staff: [
    W("Saluda y pregunta si busca un coche nuevo.", "Hello! Are you looking for a new car?|Hi! Are you looking for a new car?", "looking ; new ; car",
      "Hello! Are you looking a new car? :: We say 'look FOR'.", "Hello! You are looking for a new car? :: Question order: Are you looking…?", "q"),
    W("Dile que no se preocupe: este está perfecto y los neumáticos no están desgastados.", "Don't worry. This one is in perfect condition. The tyres aren't worn out.|Don't worry. It's in perfect condition, and the tyres aren't worn out.", "perfect ; condition ; tyres/tires ; worn",
      "Don't worry. This one is in perfect condition. The tyres aren't wear out. :: Use 'worn out'.", "Don't worry. This one is in a perfect condition. The tyres aren't worn out. :: We say 'in perfect condition' (no 'a')."),
    W("Di que quizás un poco y pregunta cuál es su oferta.", "Well, maybe a little. What's your offer?|Maybe a little. What's your offer?", "little ; offer",
      "Well, maybe a little. Which is your offer? :: We say 'What's your offer?'.", "Well, maybe a few. What's your offer? :: 'A little' (not 'a few') here.", "q"),
    W("Di que tres mil es poco y pide una explicación clara.", "Three thousand? That's not much. Can you give me a neat explanation?|That's not much. Could you give me a neat explanation?", "not much ; explanation",
      "Three thousand? That's not many. Can you give me a neat explanation? :: With money say 'not much'.", "Three thousand? That's not much. Can you give me a neat explain? :: The noun is 'explanation'.", "q"),
    W("Di que vale: tres mil doscientos y es suyo.", "All right. Three thousand two hundred, and it's yours.|OK. Three thousand two hundred and it's yours.", "thousand ; two hundred ; yours",
      "All right. Three thousands two hundreds, and it's yours. :: After a number: thousand, hundred (no s).", "All right. Three thousand two hundred, and it's your. :: The pronoun is 'yours'."),
  ], bye: "Deal! Thank you." });

/* ===================== MODULE 2 ===================== */
UNIT6({ unit: 6, name: "Up to my ears in debt", icon: "💳", who: "Bank adviser", face: "👨‍💼", client: "Customer", cface: "🧑",
  turns: [
    T("Good afternoon. What seems to be the problem?", "Di que estás endeudado hasta las orejas porque no controlaste los gastos de tu tarjeta.", "I'm up to my ears in debt because I didn't control my credit card expenses.|I'm up to my ears in debt. I didn't control my credit card expenses.", "ears ; debt ; credit card",
      "I'm up to my ears in debts because I didn't control my credit card expenses. :: The idiom is 'up to my ears in debt' (singular).", "I'm up to my ears of debt because I didn't control my credit card expenses. :: We say IN debt."),
    T("I see. When did you notice the first symptoms?", "Di que los primeros síntomas fueron que no podías pagar las facturas a tiempo.", "The first symptoms were that I couldn't pay my bills on time.|The first symptom was that I couldn't pay the bills on time.", "symptom ; pay ; bills ; time",
      "The first symptoms were that I couldn't pay my bills in time for the bank. :: Keep it simple: on time.", "The first symptoms were that I can't pay my bills on time. :: Past: I couldn't pay."),
    T("Don't panic. Many people envy those who never have money problems. Are you envious of your friends?", "Di que sí, un poco: tienes envidia de su éxito, pero no estás celoso.", "Yes, a little. I'm envious of their success, but I'm not jealous.|A little. I envy their success, but I'm not jealous.", "envious/envy ; success",
      "Yes, a little. I'm envious about their success, but I'm not jealous. :: We say envious OF.", "Yes, a little. I'm jealous of their success because I want it too. :: Wanting what others have is 'envious', not 'jealous'."),
    T("Let's be gentle with you. We could offer a mild plan: a small payment every month.", "Di que es mejor que una medida dura (harsh) y pregunta cuánto tendrías que pagar.", "That's better than a harsh measure. How much would I have to pay?|It's better than something harsh. How much would I have to pay each month?", "harsh ; how much ; pay",
      "That's better than a harsh measure. How much would I have to paid? :: After 'to' use the base verb: to pay.", "That's better than a harsh measure. How many would I have to pay? :: Money is uncountable: How much…?", "q"),
  ], end: "About two hundred pounds a month. It's not a disaster.",
  staff: [
    W("Saluda y pregunta cuál parece ser el problema.", "Good afternoon. What seems to be the problem?|Good afternoon. What's the problem?", "problem",
      "Good afternoon. What seems be the problem? :: 'Seem' + to: What seems TO be the problem?", "Good afternoon. Which is the problem? :: We say 'What's the problem?'.", "q"),
    W("Pregunta cuándo notó los primeros síntomas.", "When did you notice the first symptoms?|When did you notice the first symptoms of the problem?", "when ; notice ; symptoms",
      "When you noticed the first symptoms? :: Past questions need 'did': When did you notice…?", "When did you noticed the first symptoms? :: After 'did' use the base verb: notice.", "q"),
    W("Dile que no se asuste y pregunta si tiene envidia de sus amigos.", "Don't panic. Are you envious of your friends?|Don't panic. Do you envy your friends?", "panic ; envious/envy ; friends",
      "Don't panic. Are you envious about your friends? :: We say envious OF.", "Don't panicking. Are you envious of your friends? :: Imperative: Don't panic.", "q"),
    W("Ofrece un plan suave: un pago pequeño cada mes.", "We could offer a mild plan: a small payment every month.|We could offer you a mild plan, with a small payment every month.", "mild ; payment ; month",
      "We could offer a mild plan: a small pay every month. :: The noun is 'payment'.", "We could offer a mild plan: a small payment all months. :: We say 'every month'."),
    W("Di que serían unas doscientas libras al mes y que no es un desastre.", "About two hundred pounds a month. It's not a disaster.|About two hundred pounds a month. It isn't a disaster.", "hundred ; month ; disaster",
      "About two hundreds pounds a month. It's not a disaster. :: After a number: two hundred (no s).", "About two hundred pounds for month. It's not a disaster. :: We say 'a month'."),
  ], bye: "Thank you. That's a relief!" });

UNIT6({ unit: 7, name: "Can you mend it?", icon: "🧰", who: "Carpenter", face: "👷", client: "Customer", cface: "👩",
  turns: [
    T("Hello! What can I do for you?", "Di que la pata de tu silla está rota y pregunta si eres capaz de arreglarla.", "The leg of my chair is broken. Are you capable of mending it?|My chair's leg is broken. Could you mend it?", "chair ; broken ; mend/fix",
      "The leg of my chair is broken. Are you capable to mend it? :: We say capable OF mending.", "The leg of my chair is broke. Are you capable of mending it? :: The adjective is 'broken'.", "q"),
    T("Of course. I'll need my tools: a saw, a screwdriver and some screws.", "Pregunta cuánto tiempo requiere el trabajo.", "How long does the job require?|How much time does the job require?", "how ; long/time ; require",
      "How long requires the job? :: Questions need 'does': How long does the job require?", "How long does the job requires? :: After 'does' use the base verb: require.", "q"),
    T("About an hour. By the way, do you mend your own clothes?", "Di que sí: tienes aguja e hilo y a veces coses los pantalones rotos.", "Yes, I have a needle and thread, and I sometimes sew torn trousers.|Yes. I sometimes sew my torn trousers with a needle and thread.", "needle ; thread ; sew",
      "Yes, I have a needle and thread, and I sometimes sow torn trousers. :: 'Sow' is for seeds; with a needle we 'sew'.", "Yes, I have a needle and thread, and I sometimes sew broken trousers. :: Cloth is 'torn', not broken."),
    T("Very good! And does the colour of the chair match your table?", "Di que sí, combina perfectamente, y que el otro día compraste un mantel del mismo color.", "Yes, it matches perfectly. I bought a tablecloth of the same colour the other day.|Yes, it matches perfectly, and the other day I bought a tablecloth in the same colour.", "match ; same ; other day",
      "Yes, it matches perfectly. I bought a tablecloth of the same colour the another day. :: We say 'the other day'.", "Yes, it's matching perfectly. I bought a tablecloth of the same colour the other day. :: 'Match' is a state verb: it matches."),
  ], end: "Perfect. Come back in an hour.",
  staff: [
    W("Saluda y pregunta qué puedes hacer por el cliente.", "Hello! What can I do for you?|Hello! How can I help you?", "do/help",
      "Hello! What can I to do for you? :: After 'can' no 'to'.", "Hello! What I can do for you? :: Question order: What can I do…?", "q"),
    W("Di que claro: necesitarás tus herramientas, una sierra, un destornillador y tornillos.", "Of course. I'll need my tools: a saw, a screwdriver and some screws.|Of course. I'll need a saw, a screwdriver and some screws.", "saw ; screwdriver ; screws",
      "Of course. I'll need my tools: a saw, a screw-turner and some screws. :: The tool is a 'screwdriver'.", "Of course. I'll need my tools: a saw, a screwdriver and some nails for screwing. :: Say 'some screws'."),
    W("Di que una hora más o menos y pregunta si se arregla la ropa ella misma.", "About an hour. By the way, do you mend your own clothes?|About an hour. Do you mend your own clothes?", "hour ; mend ; clothes",
      "About a hour. By the way, do you mend your own clothes? :: Before a vowel sound: an hour.", "About an hour. By the way, you mend your own clothes? :: Questions need 'do': Do you mend…?", "q"),
    W("Pregunta si el color de la silla combina con su mesa.", "Does the colour of the chair match your table?|Does the chair's colour match your table?", "colour/color ; chair ; match ; table",
      "Does the colour of the chair matches your table? :: After 'does' use the base verb: match.", "Does the colour of the chair match with your table? :: 'Match' needs no 'with' here.", "q"),
    W("Di que perfecto y que vuelva en una hora.", "Perfect. Come back in an hour.|Perfect. Please come back in an hour.", "come back ; hour",
      "Perfect. Come back after an hour from now. :: We say 'in an hour'.", "Perfect. Come back in a hour. :: Before a vowel sound: an hour."),
  ], bye: "Great. See you later!" });

UNIT6({ unit: 8, name: "I'd like to complain", icon: "🪑", who: "Shop assistant", face: "💁", client: "Customer", cface: "🧔",
  turns: [
    T("Good morning. Can I help you?", "Di que quieres poner una queja: la mesa que compraste está mal diseñada.", "I'd like to make a complaint. The table I bought is badly designed.|I want to complain. The table I bought is badly designed.", "complain ; table ; designed",
      "I'd like to make a complain. The table I bought is badly designed. :: The noun is 'complaint'.", "I'd like to make a complaint. The table I bought is bad designed. :: Use the adverb: badly designed."),
    T("I'm sorry to hear that. Did you assemble it yourself?", "Di que sí, la montaste sin instrucciones y no tiene la forma de la foto.", "Yes, I assembled it without any instructions, and it isn't the shape in the picture.|Yes, I assembled it without instructions, and it doesn't have the shape in the photo.", "assembled ; instructions ; shape",
      "Yes, I assembled it without any instruction, and it isn't the shape in the picture. :: Use the plural: instructions.", "Yes, I assembled it without no instructions, and it isn't the shape in the picture. :: No double negative: without any instructions."),
    T("I understand. Please don't make a fuss. We'll deal with your complaint properly.", "Di que no quieres montar un escándalo, pero que si no estás satisfecho contratarás a un abogado.", "I don't want to make a fuss, but if I'm not satisfied, I'll hire a lawyer.|I'm not making a fuss, but if I'm not satisfied I'll hire a lawyer.", "fuss ; satisfied ; hire ; lawyer",
      "I don't want to do a fuss, but if I'm not satisfied, I'll hire a lawyer. :: We say MAKE a fuss.", "I don't want to make a fuss, but if I'm not satisfied, I'll rent a lawyer. :: For people we use 'hire', not 'rent'."),
    T("That won't be necessary. We can replace it approximately in a week.", "Di que admiras su actitud y que una semana te parece bien.", "I admire your attitude. A week is fine with me.|I admire your attitude, and a week is fine.", "admire ; attitude ; week",
      "I admiration your attitude. A week is fine with me. :: The verb is 'admire'.", "I admire to your attitude. A week is fine with me. :: 'Admire' has a direct object: admire your attitude."),
  ], end: "Thank you for your patience.",
  staff: [
    W("Saluda y pregunta si le puedes ayudar.", "Good morning. Can I help you?|Good morning. How can I help you?", "help",
      "Good morning. Can I helping you? :: After 'can' use the base verb: help.", "Good morning. I can help you? :: Question order: Can I help you?", "q"),
    W("Di que lo sientes y pregunta si la montó él mismo.", "I'm sorry to hear that. Did you assemble it yourself?|Sorry to hear that. Did you assemble it yourself?", "sorry ; assemble ; yourself",
      "I'm sorry to hear that. Did you assembled it yourself? :: After 'did' use the base verb: assemble.", "I'm sorry to hear that. Did you assemble it by yourselves? :: One person: yourself.", "q"),
    W("Pide que no monte un escándalo: tratarás su queja como es debido.", "Please don't make a fuss. We'll deal with your complaint properly.|Please don't make a fuss. We'll deal with the complaint properly.", "fuss ; deal ; complaint",
      "Please don't make a fuss. We'll deal your complaint properly. :: We say deal WITH a complaint.", "Please don't do a fuss. We'll deal with your complaint properly. :: We say MAKE a fuss.", "p"),
    W("Di que no hará falta: podéis cambiarla en una semana aproximadamente.", "That won't be necessary. We can replace it in approximately a week.|That won't be necessary. We can replace it in about a week.", "necessary ; replace ; week",
      "That won't be necessary. We can replace it in approximate a week. :: Use the adverb: approximately.", "That won't be necessary. We can to replace it in approximately a week. :: After 'can' no 'to'."),
    W("Dale las gracias por su paciencia.", "Thank you for your patience.|Thanks for your patience.", "thank ; patience",
      "Thank you for your patient. :: The noun is 'patience'.", "Thank you of your patience. :: We say thank you FOR."),
  ], bye: "You're welcome. Goodbye!" });

UNIT6({ unit: 9, name: "A creepy old house", icon: "🏚️", who: "Tour guide", face: "🧑‍🦱", client: "Tourist", cface: "👩",
  turns: [
    T("Welcome to the castle! They say it's haunted by ghosts.", "Di que te parece bastante espeluznante y que tienes la extraña sensación de que alguien te sigue.", "It's quite creepy. I have an odd feeling that someone is following me.|It's quite creepy. I've got an odd feeling that someone's following me.", "creepy ; odd ; following",
      "It's quite creepy. I have an even feeling that someone is following me. :: Strange = 'odd', not 'even'.", "It's quite creepy. I have an odd feeling that someone follows me. :: Now, in progress: is following."),
    T("Don't worry! Look at the paintings. Do you admire them?", "Di que te maravillas ante la valentía de los soldados de los cuadros.", "I marvel at the courage of the soldiers in the paintings.|I marvel at the soldiers' courage in the paintings.", "marvel ; courage ; soldiers",
      "I marvel of the courage of the soldiers in the paintings. :: We say marvel AT.", "I marvel at the courageous of the soldiers in the paintings. :: The noun is 'courage'."),
    T("They were very brave. Be careful: we let off fireworks at night, and they might startle you.", "Pregunta en qué ocasiones lanzan fuegos artificiales.", "On what occasions do you let off fireworks?|When do you let off fireworks?", "occasions/when ; let off ; fireworks",
      "On what occasions you let off fireworks? :: Questions need 'do': do you let off…?", "On what occasions do you let out fireworks? :: The phrasal verb is 'let off'.", "q"),
    T("On New Year's Eve. And here's our shop. These pears are not ripe yet.", "Di que no es bueno comer fruta verde y que diez libras por una caja te parece un poco excesivo.", "It isn't good to eat unripe fruit, and ten pounds for a box is a little excessive.|Unripe fruit isn't good for you, and ten pounds a box is a little excessive.", "unripe ; excessive",
      "It isn't good to eat no ripe fruit, and ten pounds for a box is a little excessive. :: The adjective is 'unripe'.", "It isn't good to eat unripe fruit, and ten pounds for a box is a little excess. :: Use the adjective: excessive."),
  ], end: "Ha! You're right. Enjoy the rest of the tour!",
  staff: [
    W("Da la bienvenida al castillo y di que dicen que está encantado por fantasmas.", "Welcome to the castle! They say it's haunted by ghosts.|Welcome to the castle! People say it's haunted.", "welcome ; castle ; haunted",
      "Welcome to the castle! They say it's haunting by ghosts. :: Passive: it's haunted.", "Welcome in the castle! They say it's haunted by ghosts. :: We say welcome TO."),
    W("Dile que no se preocupe y pregunta si admira los cuadros.", "Don't worry! Look at the paintings. Do you admire them?|Don't worry. Do you admire the paintings?", "worry ; admire ; paintings/them",
      "Don't worry! Look at the paintings. Do you admiration them? :: The verb is 'admire'.", "Don't worry! Look at the paintings. You admire them? :: Questions need 'do': Do you admire…?", "q"),
    W("Avisa de que por la noche lanzan fuegos artificiales y que podrían asustarle.", "Be careful: we let off fireworks at night, and they might startle you.|We let off fireworks at night, so they might startle you.", "let off ; fireworks ; startle",
      "Be careful: we let off fireworks at night, and they might startled you. :: After 'might' use the base verb: startle.", "Be careful: we let out fireworks at night, and they might startle you. :: The phrasal verb is 'let off'."),
    W("Di que en Nochevieja y que estas peras todavía no están maduras.", "On New Year's Eve. These pears are not ripe yet.|On New Year's Eve. And these pears aren't ripe yet.", "new year ; pears ; ripe ; yet",
      "On New Year's Eve. These pears are not ripe still. :: In negatives use 'yet'.", "In New Year's Eve. These pears are not ripe yet. :: We say ON New Year's Eve."),
    W("Di que tiene razón y que disfrute del resto de la visita.", "You're right. Enjoy the rest of the tour!|You're right! Enjoy the rest of the tour.", "right ; enjoy ; tour",
      "You have right. Enjoy the rest of the tour! :: We say 'You're right'.", "You're right. Enjoy the rest of tour! :: We say 'the rest of THE tour'."),
  ], bye: "Thanks. Goodbye!" });

/* ===================== MODULE 3 ===================== */
UNIT6({ unit: 10, name: "Firm principles", icon: "⚖️", who: "Driving instructor", face: "👨‍🏫", client: "Learner driver", cface: "🧑",
  turns: [
    T("Right. Before we start: do you know the traffic rules?", "Di que sí y que hay que obedecerlas aunque sean muy estrictas.", "Yes. We must obey them even if they're very strict.|Yes, and we must obey them even if they're strict.", "obey ; strict",
      "Yes. We must obey to them even if they're very strict. :: 'Obey' has a direct object: obey them.", "Yes. We must obey them even if they're very stiff. :: Rules are 'strict', not 'stiff'."),
    T("Good. Look, there's a tight curve ahead. What must you do?", "Di que debes reducir la velocidad: si tomas una curva demasiado rápido puedes perder el control.", "I must slow down. If you take a curve too quickly, you can lose control.|I must slow down, because if I take a curve too fast I can lose control.", "slow down ; curve ; lose control",
      "I must to slow down. If you take a curve too quickly, you can lose control. :: After 'must' no 'to'.", "I must slow down. If you take a curve too quickly, you can loose control. :: The verb is 'lose' (loose = not tight)."),
    T("Exactly. And be on your guard: other drivers can catch you off guard.", "Pregunta si la multa por ir demasiado rápido es muy alta (stiff fine).", "Is the fine for driving too fast very stiff?|Is there a stiff fine for speeding?", "stiff ; fine",
      "Is the fine for driving too fast very strict? :: A high fine is a 'stiff fine'.", "The fine for driving too fast is very stiff? :: Question order: Is the fine…?", "q"),
    T("Yes, it is. Last question: how are your feet? Your shoes look very tight.", "Di que sí, te duelen un poco los pies, pero en principio estás bien.", "Yes, my feet are a little sore, but in principle I'm fine.|My feet are a bit sore, but in principle I'm OK.", "sore ; principle",
      "Yes, my feet are a little sour, but in principle I'm fine. :: Painful = 'sore'. 'Sour' is a taste.", "Yes, my feet are a little sore, but in principal I'm fine. :: The phrase is 'in principle'."),
  ], end: "Good. Let's go, and keep both hands on the wheel!",
  staff: [
    W("Pregunta si conoce las normas de tráfico.", "Before we start: do you know the traffic rules?|Do you know the traffic rules?", "know ; traffic ; rules",
      "Before we start: you know the traffic rules? :: Questions need 'do': Do you know…?", "Before we start: do you know the traffic's rules? :: Say 'the traffic rules'.", "q"),
    W("Avisa de que hay una curva cerrada y pregunta qué debe hacer.", "Look, there's a tight curve ahead. What must you do?|There's a tight curve ahead. What must you do?", "tight ; curve ; must",
      "Look, there's a tight curve ahead. What must you to do? :: After 'must' no 'to'.", "Look, there's a strict curve ahead. What must you do? :: A sharp curve is 'tight'.", "q"),
    W("Dile que esté en guardia: otros conductores le pueden pillar desprevenido.", "Be on your guard: other drivers can catch you off guard.|Be on your guard, because other drivers can catch you off guard.", "on your guard ; off guard",
      "Be in your guard: other drivers can catch you off guard. :: We say ON your guard.", "Be on your guard: other drivers can catch you out of guard. :: We say 'catch someone OFF guard'."),
    W("Pregunta cómo tiene los pies: sus zapatos parecen muy apretados.", "How are your feet? Your shoes look very tight.|How are your feet? Your shoes look tight.", "feet ; shoes ; tight",
      "How are your foots? Your shoes look very tight. :: The plural of foot is 'feet'.", "How are your feet? Your shoes look very tightly. :: After 'look' use an adjective: tight.", "q"),
    W("Di que bien y que vais, con las dos manos en el volante.", "Good. Let's go, and keep both hands on the wheel!|Good. Let's go. Keep both hands on the wheel.", "both hands ; wheel",
      "Good. Let's go, and keep the both hands on the wheel! :: Say 'both hands' (no 'the').", "Good. Let's go, and keep both hands in the wheel! :: We say ON the wheel."),
  ], bye: "OK. I'm ready!" });

UNIT6({ unit: 11, name: "Are you keen on it?", icon: "🌷", who: "Florist", face: "👩‍🌾", client: "Customer", cface: "🧔",
  turns: [
    T("Hello! Are you looking for flowers for someone special?", "Di que sí, para tu madre: le encantan las flores (be fond of).", "Yes, for my mother. She's very fond of flowers.|Yes, they're for my mum. She's fond of flowers.", "mother/mum ; fond ; flowers",
      "Yes, for my mother. She's very fond on flowers. :: We say fond OF.", "Yes, for my mother. She's very fond of flower. :: In general use the plural: flowers."),
    T("Lovely. Tulips, daisies or carnations?", "Pregunta cuál de ellas da el aroma más agradable.", "Which of them gives off the nicest scent?|Which one gives off the nicest scent?", "which ; gives off ; scent",
      "Which of them gives out the nicest scent? :: The phrasal verb is 'give off'.", "Which of them gives off the most nice scent? :: The superlative is 'the nicest'.", "q"),
    T("Carnations, I think. Careful with those roses, they're starting to rot.", "Di que sí, huelen un poco a podrido, y pregunta si hacen encuestas sobre las flores favoritas de los clientes.", "Yes, they smell a bit rotten. Do you carry out surveys on customers' favourite flowers?|They smell rotten. Do you carry out surveys about customers' favourite flowers?", "rotten ; carry out ; surveys/survey",
      "Yes, they smell a bit rotted. Do you carry out surveys on customers' favourite flowers? :: The adjective is 'rotten'.", "Yes, they smell a bit rotten. Do you carry on surveys on customers' favourite flowers? :: 'Carry out' a survey ('carry on' = continue).", "q"),
    T("Sometimes. And I'm keen to give you a free sample of our new perfume.", "Di que te sientes halagado y que lo probarás.", "I'm flattered. I'll try it.|I'm very flattered! I'll try it.", "flattered ; try",
      "I'm flatter. I'll try it. :: Use the adjective: I'm flattered.", "I'm flattered. I'll try him. :: For a thing use 'it'."),
  ], end: "Here you are. Your mother will love the carnations!",
  staff: [
    W("Saluda y pregunta si busca flores para alguien especial.", "Hello! Are you looking for flowers for someone special?|Hi! Are you looking for flowers for someone special?", "looking ; flowers ; special",
      "Hello! Are you looking for flowers for someone specially? :: Use the adjective: someone special.", "Hello! You are looking for flowers for someone special? :: Question order: Are you looking…?", "q"),
    W("Ofrece tulipanes, margaritas o claveles.", "Lovely. Tulips, daisies or carnations?|Tulips, daisies or carnations?", "tulips ; daisies ; carnations",
      "Lovely. Tulips, daisys or carnations? :: The plural of daisy is 'daisies'.", "Lovely. Tulip, daisy or carnation? :: For a bouquet use the plurals."),
    W("Di que los claveles y avisa de que esas rosas empiezan a pudrirse.", "Carnations, I think. Careful with those roses, they're starting to rot.|Carnations. Careful with those roses: they're starting to rot.", "carnations ; roses ; rot",
      "Carnations, I think. Careful with those roses, they're starting to rotten. :: The verb is 'rot'; 'rotten' is the adjective.", "Carnations, I think. Careful with this roses, they're starting to rot. :: Plural: those roses."),
    W("Di que a veces y que tienes ganas de darle una muestra gratis del perfume nuevo.", "Sometimes. And I'm keen to give you a free sample of our new perfume.|I'm keen to give you a free sample of our new perfume.", "keen ; free ; sample ; perfume",
      "Sometimes. And I'm keen on give you a free sample of our new perfume. :: 'Keen to do' = eager to do: keen to give.", "Sometimes. And I'm keen to give you a free example of our new perfume. :: A small free product is a 'sample'."),
    W("Dale las flores y di que a su madre le encantarán los claveles.", "Here you are. Your mother will love the carnations!|Here you are. Your mum will love the carnations.", "here you are ; love ; carnations",
      "Here you have. Your mother will love the carnations! :: We say 'Here you are'.", "Here you are. Your mother will loves the carnations! :: After 'will' use the base verb: love."),
  ], bye: "Thank you so much!" });

UNIT6({ unit: 12, name: "Beyond measure", icon: "🛋️", who: "Furniture seller", face: "👨‍💼", client: "Customer", cface: "👩",
  turns: [
    T("Good afternoon! Are you looking for a couch or a sofa?", "Di que buscas un sofá, y que primero quieres medir tu salón.", "I'm looking for a sofa, but first I want to measure my living room.|A sofa, please. But first I need to measure my living room.", "sofa ; measure ; living room",
      "I'm looking for a sofa, but first I want to measurement my living room. :: The verb is 'measure'.", "I'm looking for a sofa, but first I want measure my living room. :: 'Want TO measure'."),
    T("No problem. Shall I fetch a catalogue for you?", "Di que sí, por favor, y pregunta si este banco de madera se puede sustituir por una silla.", "Yes, please. Can this wooden bench be substituted with a chair?|Yes, please. Could I substitute a chair for this bench?", "bench ; substituted/substitute ; chair",
      "Yes, please. Can this wooden bench be substitute with a chair? :: Passive: be substituted.", "Yes, please. Can this wooden bank be substituted with a chair? :: A long seat in a park is a 'bench'.", "p"),
    T("Of course. Oh no, I've just scraped the paint on the table!", "Di que no te preocupes: ese tipo de cosas te molestan sobremanera, pero esto no.", "Don't worry. That kind of thing annoys me beyond measure, but this doesn't.|Don't worry. Some things annoy me beyond measure, but not this.", "worry ; beyond measure",
      "Don't worry. That kind of thing annoys me over measure, but this doesn't. :: The phrase is 'beyond measure'.", "Don't worried. That kind of thing annoys me beyond measure, but this doesn't. :: Imperative: Don't worry."),
    T("Thank you. What strikes you most about this shop?", "Di que lo que más te llama la atención es la estatua de la entrada.", "What strikes me most is the statue at the entrance.|The statue at the entrance strikes me most.", "strikes ; statue ; entrance",
      "What strikes me most is the statute at the entrance. :: The word is 'statue'.", "What strike me most is the statue at the entrance. :: Third person: strikes."),
  ], end: "It's a copy of the Statue of Liberty. Enjoy your shopping!",
  staff: [
    W("Saluda y pregunta si busca un diván o un sofá.", "Good afternoon! Are you looking for a couch or a sofa?|Are you looking for a couch or a sofa?", "looking ; couch ; sofa",
      "Good afternoon! Are you looking a couch or a sofa? :: We say 'look FOR'.", "Good afternoon! Do you looking for a couch or a sofa? :: Present continuous: Are you looking…?", "q"),
    W("Ofrece ir a buscarle un catálogo.", "Shall I fetch a catalogue for you?|Shall I fetch you a catalogue?", "fetch ; catalogue/catalog",
      "Shall I fetch for you a catalogue? :: Say 'fetch a catalogue for you' or 'fetch you a catalogue'.", "Shall I to fetch a catalogue for you? :: After 'shall' no 'to'.", "q"),
    W("Di que claro y lamenta: acabas de rayar la pintura de la mesa.", "Of course. Oh no, I've just scraped the paint on the table!|Oh no! I've just scraped the paint on the table.", "scraped ; paint ; table",
      "Of course. Oh no, I've just scrap the paint on the table! :: Present perfect: I've just scraped.", "Of course. Oh no, I just have scraped the paint on the table! :: Word order: I've just scraped."),
    W("Da las gracias y pregunta qué es lo que más le llama la atención de la tienda.", "Thank you. What strikes you most about this shop?|What strikes you most about this shop?", "strikes ; most ; shop",
      "Thank you. What does strike you most about this shop? :: When 'what' is the subject, no 'does': What strikes you…?", "Thank you. What strikes you the more about this shop? :: We say 'most'.", "q"),
    W("Explica que es una copia de la Estatua de la Libertad y desea buenas compras.", "It's a copy of the Statue of Liberty. Enjoy your shopping!|That's a copy of the Statue of Liberty. Enjoy your shopping.", "statue ; liberty ; enjoy",
      "It's a copy of the Statue of the Liberty. Enjoy your shopping! :: The name is 'the Statue of Liberty'.", "It's a copy of the Statue of Liberty. Enjoy with your shopping! :: 'Enjoy' has no preposition."),
  ], bye: "Thank you. Bye!" });

UNIT6({ unit: 13, name: "Shelter from the storm", icon: "⛈️", who: "Hiker", face: "🧗", client: "Friend", cface: "🧑",
  turns: [
    T("Look at those clouds. I think a thunderstorm is coming!", "Di que debéis buscar refugio y que no dudes en volver.", "We should look for shelter. Let's not hesitate to go back.|We should look for shelter. Don't hesitate to go back.", "shelter ; hesitate",
      "We should look for a shelf. Let's not hesitate to go back. :: A place that protects you is a 'shelter'.", "We should look for shelter. Let's not hesitate going to back. :: We say hesitate TO go back."),
    T("But the slope is very steep here. We might slide down.", "Propón bajar despacio y usar una cuerda.", "I propose that we go down slowly and use a rope.|I propose going down slowly and using a rope.", "propose ; slowly ; rope",
      "I propose that we going down slowly and use a rope. :: After 'propose that we' use the base verb: go.", "I propose to us to go down slowly and use a rope. :: Say 'I propose that we go…' or 'I propose going…'."),
    T("Good idea. It's getting dark. Have you got a torch?", "Di que sí, tu móvil tiene linterna, pero el haz de luz no es muy fuerte.", "Yes, my mobile phone has a torch, but the beam isn't very strong.|Yes, my phone has a torch, but the beam of light isn't very strong.", "torch/flashlight ; beam",
      "Yes, my mobile phone has a torch, but the ray isn't very strong. :: The light of a torch is a 'beam'.", "Yes, my mobile phone have a torch, but the beam isn't very strong. :: Third person: has."),
    T("This is awkward. We could put up a tent here.", "Di que vale, y que es mejor que nada: es un rayo de esperanza.", "OK. It's better than nothing. It's a ray of hope.|All right. It's better than nothing, a ray of hope.", "better than nothing ; ray ; hope",
      "OK. It's better than nothing. It's a beam of hope. :: The expression is 'a ray of hope'.", "OK. It's better that nothing. It's a ray of hope. :: Comparatives use 'than'."),
  ], end: "Quick, help me put it up before the rain starts!",
  staff: [
    W("Señala las nubes: crees que viene una tormenta.", "Look at those clouds. I think a thunderstorm is coming!|Look at those clouds! A thunderstorm is coming.", "clouds ; thunderstorm ; coming",
      "Look those clouds. I think a thunderstorm is coming! :: We say look AT.", "Look at those clouds. I think a thunderstorm comes! :: Something happening now: is coming."),
    W("Di que la pendiente es muy empinada y que podríais resbalar.", "But the slope is very steep here. We might slide down.|The slope is very steep. We might slide down.", "slope ; steep ; slide",
      "But the slope is very steeply here. We might slide down. :: Use the adjective: steep.", "But the slope is very steep here. We might to slide down. :: After 'might' no 'to'."),
    W("Di que buena idea, que está oscureciendo, y pregunta si tiene linterna.", "Good idea. It's getting dark. Have you got a torch?|It's getting dark. Have you got a torch?", "dark ; torch/flashlight",
      "Good idea. It's getting darkness. Have you got a torch? :: Use the adjective: getting dark.", "Good idea. It's getting dark. Have you a torch got? :: Word order: Have you got a torch?", "q"),
    W("Di que es una situación incómoda y que podríais montar una tienda aquí.", "This is awkward. We could put up a tent here.|It's awkward. We could put up a tent here.", "awkward ; put up ; tent",
      "This is awkward. We could put on a tent here. :: For a tent we say 'put up'.", "This is awkwardly. We could put up a tent here. :: Use the adjective: awkward."),
    W("Pide que te ayude a montarla rápido antes de que empiece la lluvia.", "Quick, help me put it up before the rain starts!|Quick! Help me put it up before it starts raining.", "help ; put ; up ; before",
      "Quick, help me put up it before the rain starts! :: With a pronoun: put it up.", "Quick, help me put it up before the rain will start! :: After 'before' use the present: before the rain starts."),
  ], bye: "Done! Just in time." });

