UNIT6({ unit: 16, name: "Barbecue party", icon: "🍖", who: "Host", face: "👨‍🍳", client: "Guest", cface: "👩",
  turns: [
    T("Welcome to our barbecue! Would you like your chicken roasted on the spit or grilled?", "Di que asado en el espetón, por favor, y pregunta si las verduras están hechas al vapor.", "Roasted on the spit, please. Are the vegetables steamed?|On the spit, please. Are the vegetables steamed?", "spit ; steamed",
      "Roasted on the spit, please. Are the vegetables steam? :: Passive: Are they steamed?", "Roasted in the spit, please. Are the vegetables steamed? :: We say ON the spit.", "q"),
    T("Yes, they are. Careful! Don't walk in bare feet, the ground is hot.", "Di que apenas te habías dado cuenta y que te pondrás los zapatos.", "I barely noticed. I'll put my shoes on.|I had barely noticed. I'll put on my shoes.", "barely ; shoes",
      "I bare noticed. I'll put my shoes on. :: The adverb is 'barely'.", "I barely noticed. I'll put on them. :: With a pronoun: put them on."),
    T("Would you like some lemon on your fish?", "Di que sí, que exprima un poco; te gusta el sabor ácido.", "Yes, please squeeze a little. I like the sour taste.|Yes, squeeze some, please. I like the sour taste.", "squeeze ; sour",
      "Yes, please squeeze a little. I like the sore taste. :: The taste of lemon is 'sour'.", "Yes, please press a little. I like the sour taste. :: For lemon juice we say 'squeeze'.", "p"),
    T("I'm sorry about my brother's rude remarks. He has no regard for anyone.", "Di que no pasa nada: dale recuerdos de todas formas, y que no vas a renunciar a sus barbacoas.", "Don't worry. Give him my regards anyway. I won't give up your barbecues!|It's OK. Give him my regards anyway. I won't give up your barbecues.", "regards ; give up",
      "Don't worry. Give him my regard anyway. I won't give up your barbecues! :: The phrase is 'give someone my regards'.", "Don't worry. Give him my regards anyway. I won't give in your barbecues! :: To stop doing something is 'give up'."),
  ], end: "Ha ha! Here's your chicken, straight from the spit.",
  staff: [
    W("Da la bienvenida a la barbacoa y pregunta si quiere el pollo asado en el espetón o a la parrilla.", "Welcome to our barbecue! Would you like your chicken roasted on the spit or grilled?|Would you like your chicken roasted on the spit or grilled?", "chicken ; spit ; grilled",
      "Welcome to our barbecue! Would you like your chicken roast on the spit or grilled? :: Use the participle: roasted.", "Welcome to our barbecue! Do you like your chicken roasted on the spit or grilled? :: To offer, use 'Would you like…?'.", "q"),
    W("Di que sí, y avisa: que no ande descalza, el suelo quema.", "Yes, they are. Careful! Don't walk in bare feet, the ground is hot.|Careful! Don't walk in bare feet. The ground is hot.", "bare feet ; ground ; hot",
      "Yes, they are. Careful! Don't walk in naked feet, the ground is hot. :: For parts of the body we prefer 'bare': bare feet.", "Yes, they are. Careful! Don't walk on bare feet, the ground is hot. :: We say IN bare feet."),
    W("Pregunta si quiere un poco de limón en el pescado.", "Would you like some lemon on your fish?|Would you like lemon on your fish?", "lemon ; fish",
      "Would you like any lemon on your fish? :: In offers we use 'some'.", "Would you like some lemon in your fish? :: We put lemon ON the fish.", "q"),
    W("Discúlpate por los comentarios groseros de tu hermano: no tiene consideración por nadie.", "I'm sorry about my brother's rude remarks. He has no regard for anyone.|Sorry about my brother's rude remarks. He has no regard for anyone.", "remarks ; regard",
      "I'm sorry about my brother's rude remarks. He has no regard to anyone. :: We say 'regard FOR'.", "I'm sorry for my brother's rude remarks. He hasn't regard for anyone. :: Say 'He has no regard for anyone'."),
    W("Ríete y dale su pollo, recién salido del espetón.", "Ha ha! Here's your chicken, straight from the spit.|Here's your chicken, straight from the spit!", "chicken ; spit",
      "Ha ha! Here's your chicken, straight of the spit. :: We say 'straight FROM'.", "Ha ha! Here are your chicken, straight from the spit. :: One chicken: Here's."),
  ], bye: "Mmm, delicious. Thanks!" });

UNIT6({ unit: 17, name: "Spiders give me the shivers", icon: "🕷️", who: "Zoo keeper", face: "🧑‍🌾", client: "Visitor", cface: "🧒",
  turns: [
    T("Welcome to the reptile house! Would you like to hold this spider?", "Di que no, gracias: las arañas te dan escalofríos.", "No, thanks. Spiders give me the shivers.|No, thank you. Spiders give me the shivers!", "spiders ; shivers",
      "No, thanks. Spiders give me the shiver. :: The expression is 'give someone the shivers'.", "No, thanks. Spiders give to me the shivers. :: No 'to': give me the shivers."),
    T("Don't worry, it's tame. Look, your hands are trembling!", "Di que intentas calmarte, pero que no es en absoluto fácil.", "I'm trying to calm down, but it's by no means easy.|I'm trying to stay calm, but it's by no means easy.", "calm ; by no means",
      "I'm trying to calm down, but it's by any means easy. :: The negative phrase is 'by no means'.", "I'm trying to calm me down, but it's by no means easy. :: Say 'calm down' (no 'me')."),
    T("Contrary to what people think, most spiders are harmless.", "Pregunta si hay algún animal más tranquilo en otra parte del zoo.", "Is there a calmer animal elsewhere in the zoo?|Are there any calmer animals elsewhere in the zoo?", "calmer ; elsewhere",
      "Is there a calmer animal in elsewhere in the zoo? :: 'Elsewhere' takes no preposition.", "There is a calmer animal elsewhere in the zoo? :: Question order: Is there…?", "q"),
    T("Yes, the elephants. They're immensely powerful, but very gentle.", "Di que suena espléndido: ¡qué aventura tan extraordinaria!", "That sounds splendid. What an extraordinary adventure!|Sounds splendid! What an extraordinary adventure!", "splendid ; extraordinary ; adventure",
      "That sounds splendidly. What an extraordinary adventure! :: After 'sound' use an adjective.", "That sounds splendid. What extraordinary adventure! :: What + a/an + singular noun."),
  ], end: "Follow me, then. I urge you to take a photo with them!",
  staff: [
    W("Da la bienvenida a la casa de los reptiles y pregunta si quiere coger esta araña.", "Welcome to the reptile house! Would you like to hold this spider?|Would you like to hold this spider?", "hold ; spider",
      "Welcome to the reptile house! Would you like holding this spider? :: 'Would you like TO hold'.", "Welcome to the reptile house! Would you like to hold this spyder? :: Spelling: spider.", "q"),
    W("Tranquilízala: está domesticada. Y dile que le tiemblan las manos.", "Don't worry, it's tame. Look, your hands are trembling!|Don't worry, it's tame. Your hands are trembling!", "tame ; trembling",
      "Don't worry, it's tamed. Look, your hands are shaking off! :: Say 'your hands are trembling'.", "Don't worry, it's tame. Look, your hands are trembing! :: Spelling: trembling."),
    W("Di que, al contrario de lo que piensa la gente, la mayoría de las arañas son inofensivas.", "Contrary to what people think, most spiders are harmless.|Contrary to popular belief, most spiders are harmless.", "contrary to ; harmless",
      "On the contrary to what people think, most spiders are harmless. :: Before a noun phrase use 'contrary to'.", "Contrary to what people think, most of spiders are harmless. :: 'Most spiders' (or 'most of the spiders')."),
    W("Di que sí, los elefantes: son inmensamente poderosos pero muy mansos.", "Yes, the elephants. They're immensely powerful, but very gentle.|The elephants. They're immensely powerful but very gentle.", "elephants ; immensely ; powerful",
      "Yes, the elephants. They're immense powerful, but very gentle. :: Before an adjective use the adverb: immensely.", "Yes, the elephants. They're immensely powerless, but very gentle. :: Strong is 'powerful'."),
    W("Pide que te siga y anímale con insistencia a hacerse una foto con ellos.", "Follow me, then. I urge you to take a photo with them!|Follow me. I urge you to take a photo with them.", "follow ; urge ; photo",
      "Follow me, then. I urge you take a photo with them! :: 'Urge someone TO do'.", "Follow me, then. I urge you to make a photo with them! :: We TAKE a photo."),
  ], bye: "Brilliant. Let's go!" });

UNIT6({ unit: 18, name: "Do me a favour", icon: "🚣", who: "Boat hire man", face: "🧔", client: "Tourist", cface: "👩",
  turns: [
    T("Hi there! Can I help you?", "Pide un favor: ¿te puede alquilar una barca de remos?", "Could you do me a favour? Can I hire a rowing boat?|Can you do me a favour? I'd like to hire a rowing boat.", "do me a favour/favor ; boat",
      "Could you make me a favour? Can I hire a rowing boat? :: We DO someone a favour.", "Could you do a favour to me? Can I hire a rowing boat? :: Say 'do me a favour'.", "p"),
    T("Sure. Here's a pair of oars. Have you ever rowed before?", "Di que sí: has remado tres veranos seguidos.", "Yes, I've rowed three summers in a row.|Yes, I rowed three summers in a row.", "rowed ; in a row",
      "Yes, I've rowed three summers in a line. :: One after another = 'in a row'.", "Yes, I've rowed three summers in row. :: The phrase is 'in A row'."),
    T("Great. Be back before dark. Your boat hasn't got headlights!", "Pregunta si está a favor de dejar que los clientes se queden hasta las ocho.", "Are you in favour of letting customers stay until eight?|Would you be in favour of letting customers stay until eight?", "in favour/favor of ; until",
      "Are you in favour to let customers stay until eight? :: 'In favour of' + -ing: letting.", "You are in favour of letting customers stay until eight? :: Question order: Are you…?", "q"),
    T("OK, just this once. And watch out: one of the oars has a broken blade.", "Di que no te preocupa, pero que solo tienes un par de manos, así que remarás despacio.", "Don't worry. I've only got one pair of hands, so I'll row slowly.|No problem. I only have one pair of hands, so I'll row slowly.", "pair ; hands ; row",
      "Don't worry. I've only got one couple of hands, so I'll row slowly. :: Two things that go together: a pair.", "Don't worry. I've only got one pair of hands, so I'll rowing slowly. :: 'Will' + base verb: row."),
  ], end: "Ha ha! Enjoy the lake. And remember: you owe me a favour!",
  staff: [
    W("Saluda y pregunta si puedes ayudarle.", "Hi there! Can I help you?|Hello! Can I help you?", "help",
      "Hi there! Can I help to you? :: 'Help' takes a direct object: help you.", "Hi there! Do I can help you? :: Question: Can I help you?", "q"),
    W("Di que claro: aquí tiene un par de remos. Pregunta si ha remado antes.", "Sure. Here's a pair of oars. Have you ever rowed before?|Here's a pair of oars. Have you ever rowed before?", "pair ; oars ; rowed",
      "Sure. Here's a pair of oars. Did you ever row before? :: Life experience: Have you ever rowed…?", "Sure. Here's a pair of ores. Have you ever rowed before? :: Spelling: oars.", "q"),
    W("Pide que vuelva antes de que oscurezca: la barca no tiene faros.", "Great. Be back before dark. Your boat hasn't got headlights!|Be back before dark. The boat hasn't got headlights!", "before dark ; headlights",
      "Great. Be back before it gets darkness. Your boat hasn't got headlights! :: Say 'before dark' or 'before it gets dark'.", "Great. Be back before dark. Your boat hasn't got headlight! :: Plural: headlights."),
    W("Di que vale, solo por esta vez, y avisa de que uno de los remos tiene la pala rota.", "OK, just this once. And watch out: one of the oars has a broken blade.|Just this once. Watch out: one oar has a broken blade.", "once ; oars/oar ; blade",
      "OK, just this once. And watch out: one of the oar has a broken blade. :: 'One of the' + plural: oars.", "OK, just this once. And watch out: one of the oars has a broke blade. :: Adjective: broken."),
    W("Ríete, desea que disfrute del lago y recuérdale que te debe un favor.", "Ha ha! Enjoy the lake. And remember: you owe me a favour!|Enjoy the lake! Remember, you owe me a favour.", "enjoy ; owe ; favour/favor",
      "Ha ha! Enjoy the lake. And remember: you own me a favour! :: To have a debt is 'owe'.", "Ha ha! Enjoy the lake. And remember: you owe to me a favour! :: Say 'you owe me a favour'."),
  ], bye: "Thanks a lot. See you later!" });

UNIT6({ unit: 19, name: "A rude customer", icon: "🥢", who: "Waiter", face: "🧑‍🍳", client: "Diner", cface: "🧑",
  turns: [
    T("Good evening. Would you like chopsticks or a knife and fork?", "Di que palillos, por favor: lo que aprendiste en China se te quedó grabado.", "Chopsticks, please. What I learnt in China really stuck in my mind.|Chopsticks, please. What I learned in China stuck in my mind.", "chopsticks ; stuck",
      "Chopsticks, please. What I learnt in China really sticked in my mind. :: The past of stick is 'stuck'.", "Chopstick, please. What I learnt in China really stuck in my mind. :: They come in pairs: chopsticks."),
    T("Sorry about the noise. That man is telling crude jokes.", "Di que es muy maleducado y que además escupió en el suelo.", "He's very rude. And he spat on the floor!|He's really rude. He even spat on the floor!", "rude ; spat",
      "He's very rude. And he spitted on the floor! :: The past of spit is 'spat'.", "He's very rough. And he spat on the floor! :: Impolite = 'rude'."),
    T("I'm so sorry. I'll ask him to leave. Is your food all right?", "Di que la sopa está muy agria y que has tenido que escupirla.", "The soup is very sour. I had to spit it out.|The soup is really sour. I had to spit it out.", "sour ; spit it out",
      "The soup is very sour. I had to spit out it. :: With a pronoun: spit it out.", "The soup is very sore. I had to spit it out. :: The taste of lemon or bad milk is 'sour'."),
    T("Oh dear. Let me bring you some ice cream instead, on the house.", "Da las gracias y di, en broma, que te lamerás las heridas con un helado.", "Thanks. I'll lick my wounds with an ice cream!|Thank you. I'll lick my wounds with an ice cream.", "lick ; wounds",
      "Thanks. I'll like my wounds with an ice cream! :: The verb is 'lick'.", "Thanks. I'll lick my wounds with a ice cream! :: Before a vowel sound: an ice cream."),
  ], end: "Here you are. And here's a card to stick on your fridge: ten per cent off next time!",
  staff: [
    W("Saluda y pregunta si quiere palillos o cuchillo y tenedor.", "Good evening. Would you like chopsticks or a knife and fork?|Would you like chopsticks or a knife and fork?", "chopsticks ; knife ; fork",
      "Good evening. Would you like chopsticks or a knife and a fork? :: We usually say 'a knife and fork'.", "Good evening. Do you like chopsticks or a knife and fork? :: To offer, use 'Would you like…?'.", "q"),
    W("Discúlpate por el ruido: ese hombre está contando chistes groseros.", "Sorry about the noise. That man is telling crude jokes.|Sorry about the noise. That man is telling crude jokes.", "noise ; crude ; jokes",
      "Sorry about the noise. That man is saying crude jokes. :: We TELL jokes.", "Sorry about the noise. That man is telling crude joke. :: Plural: jokes."),
    W("Discúlpate, di que le pedirás que se vaya y pregunta si la comida está bien.", "I'm so sorry. I'll ask him to leave. Is your food all right?|I'm sorry. I'll ask him to leave. Is your food OK?", "ask him to leave ; food",
      "I'm so sorry. I'll ask him leave. Is your food all right? :: 'Ask someone TO do'.", "I'm so sorry. I'll ask him to leave. Is your food alright good? :: Ask 'Is your food all right?'.", "q"),
    W("Ofrece traerle helado en su lugar, invita la casa.", "Oh dear. Let me bring you some ice cream instead, on the house.|Let me bring you some ice cream instead, on the house.", "bring ; ice cream ; on the house",
      "Oh dear. Let me to bring you some ice cream instead, on the house. :: After 'let me' no 'to'.", "Oh dear. Let me bring you some ice cream instead, of the house. :: Free from the restaurant = 'on the house'."),
    W("Dale el helado y una tarjeta para pegar en la nevera: un diez por ciento de descuento la próxima vez.", "Here you are. And here's a card to stick on your fridge: ten per cent off next time!|Here's a card to stick on your fridge: ten per cent off next time.", "stick ; fridge ; off",
      "Here you are. And here's a card to stuck on your fridge: ten per cent off next time! :: After 'to', base verb: stick.", "Here you are. And here's a card to stick in your fridge: ten per cent off next time! :: On the door: ON your fridge."),
  ], bye: "Thank you. Good night!" });

/* ===================== MODULE 6 ===================== */
UNIT6({ unit: 20, name: "Is it contagious?", icon: "🤒", who: "Doctor", face: "👩‍⚕️", client: "Patient", cface: "🧑",
  turns: [
    T("Good morning. What seems to be the problem?", "Di que tienes mucha fiebre y que crees que tienes la gripe.", "I've got a high fever. I think I've got the flu.|I have a high fever. I think I have the flu.", "fever ; flu",
      "I've got a tall fever. I think I've got the flu. :: A strong fever is a 'high' fever.", "I've got a high fever. I think I've got the flue. :: The illness is 'the flu'."),
    T("Let me see. Yes, it's the flu. Have you been vaccinated this year?", "Di que no: creías que eras inmune.", "No, I haven't. I thought I was immune.|No, I haven't. I thought I was immune to it.", "immune",
      "No, I didn't. I thought I was immune. :: Answer 'Have you…?' with 'No, I haven't'.", "No, I haven't. I thought I am immune. :: After 'I thought', use the past: I was."),
    T("You should stay at home for a few days.", "Pregunta si la gripe es contagiosa: tu hijo es muy pequeño.", "Is the flu contagious? My son is very young.|Is flu contagious? My son is very small.", "contagious/infectious ; son",
      "Is the flu contagion? My son is very young. :: Use the adjective: contagious.", "The flu is contagious? My son is very young. :: Question order: Is the flu…?", "q"),
    T("Yes, very. Take these pills, and come back if there's no improvement.", "Pregunta cuánto tardarás en notar una mejora.", "How soon will I notice an improvement?|How long until I notice an improvement?", "improvement",
      "How soon will I notice an improve? :: The noun is 'improvement'.", "How soon I will notice an improvement? :: Question order: will I notice.", "q"),
  ], end: "In two or three days. Rest, drink lots of water and get well soon!",
  staff: [
    W("Saluda y pregunta cuál parece ser el problema.", "Good morning. What seems to be the problem?|Hello. What seems to be the problem?", "seems ; problem",
      "Good morning. What does seem to be the problem? :: 'What' is the subject: What seems…?", "Good morning. What seems be the problem? :: 'Seem TO be'.", "q"),
    W("Di que sí, es gripe, y pregunta si se ha vacunado este año.", "Let me see. Yes, it's the flu. Have you been vaccinated this year?|It's the flu. Have you been vaccinated this year?", "flu ; vaccinated",
      "Let me see. Yes, it's the flu. Have you vaccinated this year? :: Passive: Have you BEEN vaccinated?", "Let me see. Yes, it's the flu. Did you be vaccinated this year? :: Use the present perfect: Have you been…?", "q"),
    W("Aconséjale quedarse en casa unos días.", "You should stay at home for a few days.|You should stay at home for a few days.", "should ; stay ; home",
      "You should to stay at home for a few days. :: After 'should' no 'to'.", "You should stay in home for a few days. :: We say 'at home'."),
    W("Di que sí, mucho. Que tome estas pastillas y vuelva si no mejora.", "Yes, very. Take these pills, and come back if there's no improvement.|Take these pills and come back if there's no improvement.", "pills ; improvement",
      "Yes, very. Take these pills, and come back if there won't be any improvement. :: After 'if', use the present: if there's no improvement.", "Yes, very. Take these pills, and come back if there's no improve. :: The noun is 'improvement'."),
    W("Di que en dos o tres días; que descanse, beba mucha agua y que se mejore.", "In two or three days. Rest, drink lots of water and get well soon!|Two or three days. Rest, drink lots of water and get well soon.", "rest ; water ; get well",
      "In two or three days. Rest, drink lots of water and get good soon! :: The phrase is 'get well soon'.", "In two or three days. Rest, drink a lot water and get well soon! :: Say 'lots of water' or 'a lot of water'."),
  ], bye: "Thank you, doctor." });

UNIT6({ unit: 21, name: "At the dry cleaner's", icon: "👔", who: "Dry cleaner", face: "👨‍🔧", client: "Customer", cface: "👩",
  turns: [
    T("Hello! What can I do for you?", "Di que tu traje tiene una mancha de vino que no sale.", "My suit has a wine stain and it won't come out.|There's a wine stain on my suit and it won't come out.", "stain ; suit ; come out",
      "My suit has a wine stain and it won't go out. :: A stain 'comes out'.", "My suit has a wine's stain and it won't come out. :: Say 'a wine stain'."),
    T("No problem. Anything else?", "Di que sí: también estas sábanas y estas almohadas.", "Yes, these sheets and pillows too.|Yes, these sheets and these pillows as well.", "sheets ; pillows",
      "Yes, these sheeps and pillows too. :: Bed linen: sheets (sheep are animals).", "Yes, these sheet and pillows too. :: Plural after 'these': sheets."),
    T("Atchoo! Sorry, I've got a cold. I can't stop sneezing and sniffing.", "Di «Jesús» y pregunta si tiene algún remedio casero.", "Bless you! Have you got any home remedies?|Bless you! Do you know any home remedies?", "bless you ; remedies/remedy",
      "Health! Have you got any home remedies? :: In English we say 'Bless you!'.", "Bless you! Have you got any home remedys? :: The plural is 'remedies'.", "q"),
    T("Onion soup! Now, this stain is a bit complicated. It could take a week.", "Pide que te aclare: ¿estará listo el viernes?", "Could you clarify? Will it be ready on Friday?|Can you clarify that? Will it be ready on Friday?", "clarify ; ready ; friday",
      "Could you clear? Will it be ready on Friday? :: To make something clear is 'clarify'.", "Could you clarify? Will it be ready in Friday? :: Days: ON Friday.", "q"),
  ], end: "Yes, on Friday at the latest. Here's your ticket.",
  staff: [
    W("Saluda y pregunta qué puedes hacer por ella.", "Hello! What can I do for you?|Good morning! What can I do for you?", "what ; do for you",
      "Hello! What can I make for you? :: The phrase is 'What can I DO for you?'.", "Hello! What I can do for you? :: Question order: What can I do…?", "q"),
    W("Di que no hay problema y pregunta si hay algo más.", "No problem. Anything else?|No problem. Is there anything else?", "problem ; anything else",
      "No problem. Something else? :: In questions use 'anything': Anything else?", "No problem. Anything other? :: Say 'anything else'.", "q"),
    W("Estornuda, discúlpate: estás resfriado y no paras de estornudar y sorberte la nariz.", "Atchoo! Sorry, I've got a cold. I can't stop sneezing and sniffing.|Sorry, I've got a cold. I can't stop sneezing and sniffing.", "cold ; sneezing ; sniffing",
      "Atchoo! Sorry, I've got a cold. I can't stop to sneeze and sniff. :: 'Can't stop' + -ing.", "Atchoo! Sorry, I've got a cool. I can't stop sneezing and sniffing. :: The illness is 'a cold'."),
    W("Recomienda sopa de cebolla y di que la mancha es complicada: podría tardar una semana.", "Onion soup! Now, this stain is a bit complicated. It could take a week.|Onion soup! This stain is complicated. It could take a week.", "onion ; stain ; complicated",
      "Onion soup! Now, this stain is a bit complicate. It could take a week. :: The adjective is 'complicated'.", "Onion soup! Now, this stain is a bit complicated. It could last a week. :: For time needed we say 'take'."),
    W("Di que sí, el viernes como muy tarde, y dale su resguardo.", "Yes, on Friday at the latest. Here's your ticket.|On Friday at the latest. Here's your ticket.", "friday ; latest ; ticket",
      "Yes, on Friday at the last. Here's your ticket. :: The phrase is 'at the latest'.", "Yes, on Friday at latest. Here's your ticket. :: 'At THE latest'."),
  ], bye: "Perfect. Thank you!" });

UNIT6({ unit: 22, name: "Stung by a bee", icon: "🐝", who: "Pharmacist", face: "👨‍⚕️", client: "Customer", cface: "👩",
  turns: [
    T("Hello. What's happened to your hand?", "Di que te ha picado una abeja y que se ha hinchado.", "A bee has stung me and it's swollen.|I've been stung by a bee and it's swollen.", "bee ; stung ; swollen",
      "A bee has stinged me and it's swollen. :: The past participle of sting is 'stung'.", "A bee has stung me and it's swelled. :: As an adjective use 'swollen'."),
    T("Let me look. Is the sting still in your skin?", "Di que no, que lo quitaste, pero que escuece mucho.", "No, I removed it, but it stings a lot.|No, I took it out, but it stings a lot.", "stings",
      "No, I removed it, but it stinks a lot. :: A burning pain 'stings' ('stinks' = smells bad).", "No, I removed it, but it sting a lot. :: Third person: it stings."),
    T("Put this cold compress on it. It will reduce the swelling.", "Pregunta si tiene algo para el pecho de tu marido: tose mucho.", "Have you got anything for my husband's chest? He's coughing a lot.|Do you have anything for my husband's chest? He's coughing a lot.", "chest ; coughing",
      "Have you got anything for my husband's breast? He's coughing a lot. :: For lungs and coughs we say 'chest'.", "Have you got anything for my husband's chest? He's coughing very much. :: Say 'coughing a lot'.", "q"),
    T("He should see a doctor. A cough like that shouldn't be swept under the carpet.", "Di que tiene razón y que pedirás cita hoy.", "You're right. I'll make an appointment today.|You're right. I'll book an appointment today.", "right ; appointment",
      "You have reason. I'll make an appointment today. :: In English: You're right.", "You're right. I'll do an appointment today. :: We MAKE an appointment."),
  ], end: "Good idea. And keep these medicines in a cupboard, away from children.",
  staff: [
    W("Saluda y pregunta qué le ha pasado en la mano.", "Hello. What's happened to your hand?|Hello. What happened to your hand?", "happened ; hand",
      "Hello. What's happened with your hand? :: We say 'happen TO'.", "Hello. What has your hand happened? :: Say 'What's happened to your hand?'.", "q"),
    W("Pide verla y pregunta si el aguijón sigue en la piel.", "Let me look. Is the sting still in your skin?|Let me see. Is the sting still in your skin?", "sting ; still ; skin",
      "Let me look. Is still the sting in your skin? :: Word order: Is the sting still…?", "Let me to look. Is the sting still in your skin? :: After 'let me' no 'to'.", "q"),
    W("Dile que se ponga esta compresa fría: reducirá la hinchazón.", "Put this cold compress on it. It will reduce the swelling.|Put this cold compress on it to reduce the swelling.", "compress ; reduce ; swelling",
      "Put this cold compress on it. It will reduce the swollen. :: The noun is 'swelling'.", "Put this cold compress over it. It will reduce the swelling. :: Say 'put it ON'."),
    W("Di que debería ir al médico: una tos así no se debe esconder debajo de la alfombra.", "He should see a doctor. A cough like that shouldn't be swept under the carpet.|He should see a doctor. Don't sweep a cough like that under the carpet.", "doctor ; swept/sweep ; carpet",
      "He should see a doctor. A cough like that shouldn't be sweeped under the carpet. :: The participle of sweep is 'swept'.", "He should see a doctor. A cough like that shouldn't be swept under the rug carpet floor. :: The idiom is 'sweep something under the carpet'."),
    W("Di que buena idea, y que guarde los medicamentos en un armario, lejos de los niños.", "Good idea. And keep these medicines in a cupboard, away from children.|Keep these medicines in a cupboard, away from children.", "cupboard ; away from ; children",
      "Good idea. And keep these medicines in a cupboard, far of children. :: Say 'away from children'.", "Good idea. And keep these medicines in a cubboard, away from children. :: Spelling: cupboard."),
  ], bye: "Thank you very much!" });

UNIT6({ unit: 23, name: "A slippery path", icon: "🥾", who: "Mountain guide", face: "🧗‍♀️", client: "Hiker", cface: "🧑",
  turns: [
    T("Stop! Your shoelaces are undone.", "Da las gracias y di que te los atarás antes de resbalar.", "Thanks. I'll tie them before I slip.|Thank you. I'll tie them before I slip.", "tie ; slip",
      "Thanks. I'll tie them before I'll slip. :: After 'before', use the present: before I slip.", "Thanks. I'll tie them before I slide. :: Losing your footing on a wet floor is 'slip'."),
    T("Good. Be careful, the path is very muddy and slippery here.", "Pregunta si hay un camino menos resbaladizo.", "Is there a less slippery path?|Isn't there a less slippery path?", "less ; slippery",
      "Is there a less slipping path? :: The adjective is 'slippery'.", "There is a less slippery path? :: Question order: Is there…?", "q"),
    T("No, this is the only way. Don't despair, we're nearly there!", "Di que no te vas a rendir al cansancio (yield).", "Don't worry. I won't yield to tiredness.|I won't yield to tiredness!", "yield ; tiredness",
      "Don't worry. I won't yield at tiredness. :: We say 'yield TO'.", "Don't worry. I don't yield to tiredness. :: A decision about the future: I won't."),
    T("That's the spirit! Look, the hut is just behind those trees.", "Di qué alivio, y que estás deseando quitarte las botas llenas de barro.", "What a relief! I can't wait to slip my muddy boots off.|What a relief! I can't wait to take off my muddy boots.", "relief ; muddy ; boots",
      "What a relieve! I can't wait to slip my muddy boots off. :: The noun is 'relief'.", "What a relief! I can't wait for slipping my muddy boots off. :: 'Can't wait TO do'."),
  ], end: "Me too! Hot chocolate for everyone.",
  staff: [
    W("Pide que pare: lleva los cordones desatados.", "Stop! Your shoelaces are undone.|Wait! Your shoelaces are undone.", "shoelaces/laces ; undone",
      "Stop! Your shoelaces are undid. :: The participle is 'undone'.", "Stop! Your shoelace are undone. :: Plural: shoelaces."),
    W("Avisa: el camino está muy embarrado y resbaladizo aquí.", "Good. Be careful, the path is very muddy and slippery here.|Be careful, the path is very muddy and slippery.", "muddy ; slippery",
      "Good. Be careful, the path is very mud and slippery here. :: Use the adjective: muddy.", "Good. Be carefully, the path is very muddy and slippery here. :: 'Be careful' (adjective)."),
    W("Di que no, es el único camino; que no se desespere, ya casi estáis.", "No, this is the only way. Don't despair, we're nearly there!|This is the only way. Don't despair, we're nearly there.", "only way ; despair ; nearly",
      "No, this is the only way. Don't despair, we're nearly here! :: The place you're going to is 'there'.", "No, this is the only way. Don't despairing, we're nearly there! :: Imperative: Don't despair."),
    W("Anímale y señala que el refugio está justo detrás de esos árboles.", "That's the spirit! Look, the hut is just behind those trees.|Look, the hut is just behind those trees!", "hut ; behind ; trees",
      "That's the spirit! Look, the hut is just behind of those trees. :: 'Behind' takes no 'of'.", "That's the spirit! Look, the hut is just behind these trees. :: Things far away: those trees."),
    W("Di que tú también, y que hay chocolate caliente para todos.", "Me too! Hot chocolate for everyone.|Me too! Hot chocolate for everybody!", "hot chocolate ; everyone/everybody",
      "Me too! Hot chocolate for all everyone. :: Say 'for everyone'.", "Me neither! Hot chocolate for everyone. :: To agree with a positive idea: Me too."),
  ], bye: "Yes! Thanks for everything." });

/* ===================== MODULE 7 ===================== */
UNIT6({ unit: 24, name: "A tempting destination", icon: "🏝️", who: "Travel agent", face: "👩‍💼", client: "Customer", cface: "🧔",
  turns: [
    T("Good afternoon. Where would you like to travel?", "Di que aún no lo has decidido y pregunta qué destino recomienda.", "I haven't decided yet. Which destination would you recommend?|I haven't decided yet. What destination do you recommend?", "destination ; recommend",
      "I haven't decided yet. Which destiny would you recommend? :: The place you travel to is your 'destination'.", "I haven't decided yet. Which destination would you recommend me? :: 'Recommend' + the thing: no 'me'.", "q"),
    T("How about the Maldives? This luxury hotel is on special offer.", "Di que es muy tentador, pero que es difícil resistir la tentación de gastar demasiado.", "It's very tempting, but it's hard to resist the temptation to spend too much.|It's tempting, but it's hard to resist the temptation to spend too much.", "tempting ; resist ; temptation",
      "It's very tempted, but it's hard to resist the temptation to spend too much. :: Something attractive is 'tempting'.", "It's very tempting, but it's hard to resist to the temptation to spend too much. :: 'Resist' takes no 'to'."),
    T("I understand. And remember: you'll need sun cream to shield your skin.", "Pregunta si el precio incluye un seguro que te proteja si cancelan el vuelo.", "Does the price include insurance to shield me if the flight is cancelled?|Does the price include insurance in case the flight is cancelled?", "include ; insurance",
      "Does the price includes insurance to shield me if the flight is cancelled? :: After 'does', base verb: include.", "Does the price include insurance to shield me if the flight will be cancelled? :: After 'if', use the present.", "q"),
    T("Yes, it does. So, shall I book it for you?", "Di que sí: ¡debe de ser el destino!", "Yes! It must be fate.|Yes, please! It must be fate.", "fate",
      "Yes! It must be destination. :: What is meant to happen is 'fate'.", "Yes! It must to be fate. :: After 'must' no 'to'."),
  ], end: "Wonderful. I'll send you the tickets by email.",
  staff: [
    W("Saluda y pregunta adónde le gustaría viajar.", "Good afternoon. Where would you like to travel?|Hello. Where would you like to travel?", "where ; like to travel",
      "Good afternoon. Where would you like to travel to there? :: Say 'Where would you like to travel?'.", "Good afternoon. Where you would like to travel? :: Question order: Where would you…?", "q"),
    W("Propón las Maldivas: este hotel de lujo está de oferta.", "How about the Maldives? This luxury hotel is on special offer.|What about the Maldives? This luxury hotel is on special offer.", "maldives ; luxury ; offer",
      "How about the Maldives? This luxury hotel is in special offer. :: We say ON offer.", "How about go to the Maldives? This luxury hotel is on special offer. :: 'How about' + noun or -ing."),
    W("Di que lo entiendes y recuérdale que necesitará crema solar para proteger la piel.", "I understand. And remember: you'll need sun cream to shield your skin.|Remember, you'll need sun cream to shield your skin.", "sun cream ; shield ; skin",
      "I understand. And remember: you'll need sun cream for shield your skin. :: Purpose: TO shield.", "I understand. And remember: you'll need sun cream to shield your leather. :: On your body: skin."),
    W("Di que sí lo incluye y pregunta si se lo reservas.", "Yes, it does. So, shall I book it for you?|Yes, it does. Shall I book it for you?", "shall ; book",
      "Yes, it includes. So, shall I book it for you? :: Short answer: Yes, it does.", "Yes, it does. So, shall I to book it for you? :: After 'shall' no 'to'.", "q"),
    W("Di que estupendo y que le enviarás los billetes por correo electrónico.", "Wonderful. I'll send you the tickets by email.|Great. I'll send you the tickets by email.", "send ; tickets ; email",
      "Wonderful. I'll send you the tickets for email. :: The means: BY email.", "Wonderful. I'll send to you the tickets by email. :: 'Send you the tickets' (no 'to')."),
  ], bye: "Thank you so much!" });

UNIT6({ unit: 25, name: "On the ferry", icon: "⛴️", who: "Ship's captain", face: "👨‍✈️", client: "Passenger", cface: "👩",
  turns: [
    T("Are you all right? You look very pale.", "Di que sufres mareos por el movimiento.", "I suffer from motion sickness.|Not really. I suffer from motion sickness.", "motion sickness",
      "I suffer of motion sickness. :: We say 'suffer FROM'.", "I suffer from move sickness. :: The term is 'motion sickness'."),
    T("Try to stay motionless and look at the horizon. I'm the captain, by the way.", "Pregunta si tiene un rango superior al del oficial que te atendió antes.", "Are you superior in rank to the officer who helped me before?|Is your rank superior to the officer who helped me before?", "superior ; rank",
      "Are you superior in rank than the officer who helped me before? :: We say 'superior TO'.", "You are superior in rank to the officer who helped me before? :: Question order: Are you…?", "q"),
    T("Yes, I'm the highest rank on board. Why?", "Di que ese oficial fue maleducado y te hizo sentir inferior.", "He was rude and he made me feel inferior.|That officer was rude. He made me feel inferior.", "rude ; inferior",
      "He was rude and he made me to feel inferior. :: 'Make someone do' (no 'to').", "He was rude and he made me feel inferiority. :: Use the adjective: inferior."),
    T("I'm very sorry. I'll speak to him. Is there anything else?", "Pregunta cómo puedes hacer una señal si necesitas ayuda por la noche.", "How can I signal if I need help at night?|How do I signal if I need help at night?", "signal ; help ; night",
      "How can I signal if I will need help at night? :: After 'if', use the present.", "How I can signal if I need help at night? :: Question order: How can I…?", "q"),
  ], end: "Just press this red button. It sets everything in motion.",
  staff: [
    W("Pregunta si está bien: se le ve muy pálida.", "Are you all right? You look very pale.|Are you OK? You look very pale.", "all right/ok ; pale",
      "Are you all right? You look very palely. :: After 'look' use an adjective: pale.", "Are you all right? You look very pail. :: Spelling: pale.", "q"),
    W("Aconséjale quedarse inmóvil y mirar el horizonte, y di que eres el capitán.", "Try to stay motionless and look at the horizon. I'm the captain, by the way.|Stay motionless and look at the horizon. I'm the captain.", "motionless ; horizon ; captain",
      "Try to stay motionless and look the horizon. I'm the captain, by the way. :: We say 'look AT'.", "Try to stay motionlessly and look at the horizon. I'm the captain, by the way. :: After 'stay' use an adjective."),
    W("Di que sí, que tienes el rango más alto a bordo, y pregunta por qué.", "Yes, I'm the highest rank on board. Why?|Yes, I have the highest rank on board. Why?", "highest ; rank ; board",
      "Yes, I'm the most high rank on board. Why? :: Superlative: the highest.", "Yes, I'm the highest rank in board. Why? :: On a ship: ON board.", "q"),
    W("Discúlpate, di que hablarás con él y pregunta si necesita algo más.", "I'm very sorry. I'll speak to him. Is there anything else?|I'm sorry. I'll speak to him. Anything else?", "speak to him ; anything else",
      "I'm very sorry. I'll speak him. Is there anything else? :: We say 'speak TO him'.", "I'm very sorry. I'll speak to him. Is there something other? :: Say 'anything else'.", "q"),
    W("Dile que solo tiene que pulsar el botón rojo: pone todo en marcha.", "Just press this red button. It sets everything in motion.|Press this red button. It sets everything in motion.", "button ; motion",
      "Just press this red button. It sets everything on motion. :: The phrase is 'set something IN motion'.", "Just press this red button. It set everything in motion. :: Third person: it sets."),
  ], bye: "Thank you, captain." });

UNIT6({ unit: 26, name: "Booking a table", icon: "📞", who: "Restaurant receptionist", face: "👩‍💼", client: "Caller", cface: "🧑",
  turns: [
    T("Good evening, Bella Vista restaurant. How can I help you?", "Di que quieres hacer una reserva para cuatro el sábado.", "I'd like to make a reservation for four on Saturday.|I'd like to reserve a table for four on Saturday.", "reservation/reserve ; four ; saturday",
      "I'd like to do a reservation for four on Saturday. :: We MAKE a reservation.", "I'd like to make a reservation for four in Saturday. :: Days: ON Saturday."),
    T("Certainly. At what time exactly?", "Di que a las ocho en punto, exactamente.", "At eight o'clock precisely.|At eight o'clock, precisely.", "eight ; precisely",
      "At eight o'clock precise. :: After a time use the adverb: precisely.", "In eight o'clock precisely. :: Clock times: AT eight."),
    T("Perfect. Would you like a table by the window?", "Di que sí, por favor, y pregunta si hay que pagar por adelantado.", "Yes, please. Do we have to pay in advance?|Yes, please. Do I need to pay in advance?", "pay ; in advance",
      "Yes, please. Do we have to pay by advance? :: The phrase is 'in advance'.", "Yes, please. We have to pay in advance? :: Question: Do we have to…?", "q"),
    T("Just a ten-euro deposit. Could I have your phone number?", "Da tu número (600 123 456) y pide que lo repita para comprobar que es exacto.", "It's 600 123 456. Could you repeat it to check it's accurate?|600 123 456. Could you repeat it to check it's correct and accurate?", "repeat ; accurate/exact",
      "It's 600 123 456. Could you repeat it to check it's accurately? :: After 'is' use an adjective: accurate.", "It's 600 123 456. Could you repeat it for check it's accurate? :: Purpose: TO check.", "p"),
  ], end: "600 123 456. Yes, that's exactly right. See you on Saturday!",
  staff: [
    W("Contesta al teléfono con el nombre del restaurante y pregunta en qué puedes ayudar.", "Good evening, Bella Vista restaurant. How can I help you?|Bella Vista restaurant. How can I help you?", "restaurant ; help",
      "Good evening, Bella Vista restaurant. How can I help to you? :: 'Help you' (no 'to').", "Good evening, Bella Vista restaurant. How I can help you? :: Question order: How can I…?", "q"),
    W("Di que por supuesto y pregunta a qué hora exactamente.", "Certainly. At what time exactly?|Certainly. What time exactly?", "time ; exactly",
      "Certainly. At what time exact? :: Use the adverb: exactly.", "Certainly. In what time exactly? :: Clock times: AT what time.", "q"),
    W("Di que perfecto y pregunta si quiere una mesa junto a la ventana.", "Perfect. Would you like a table by the window?|Would you like a table by the window?", "table ; window",
      "Perfect. Would you like a table by the windows? :: One window: by the window.", "Perfect. Do you like a table by the window? :: To offer: Would you like…?", "q"),
    W("Di que solo una señal de diez euros y pide su número de teléfono.", "Just a ten-euro deposit. Could I have your phone number?|Only a ten-euro deposit. Can I have your phone number?", "deposit ; phone number",
      "Just a ten-euros deposit. Could I have your phone number? :: Before a noun, the number stays singular: a ten-euro deposit.", "Just a ten-euro deposit. Could I have your phone's number? :: Say 'your phone number'.", "q"),
    W("Repite el número, confirma que es exacto y despídete hasta el sábado.", "600 123 456. Yes, that's exactly right. See you on Saturday!|That's exactly right. See you on Saturday!", "exactly ; right ; saturday",
      "600 123 456. Yes, that's exact right. See you on Saturday! :: Before an adjective use the adverb: exactly right.", "600 123 456. Yes, that's exactly right. See you the Saturday! :: Say 'See you on Saturday'."),
  ], bye: "Great. Thank you!" });

UNIT6({ unit: 27, name: "House hunting", icon: "🏡", who: "Estate agent", face: "👨‍💼", client: "House buyer", cface: "👩",
  turns: [
    T("Good morning! What kind of house are you looking for?", "Di que una casa independiente con jardín, no una adosada en hilera.", "A detached house with a garden, not a terraced one.|I'm looking for a detached house with a garden, not a terraced one.", "detached ; terraced",
      "A detaching house with a garden, not a terraced one. :: The adjective is 'detached'.", "A detached house with a garden, not a terraced ones. :: One house: one."),
    T("I've got a lovely cottage with a thatched roof. It's a bit old, though.", "Pregunta si se podría adaptar para una persona en silla de ruedas.", "Could it be adapted for a person in a wheelchair?|Could it be adapted for someone in a wheelchair?", "adapted ; wheelchair",
      "Could it be adjusted for a person in a wheelchair? :: For a permanent change we say 'adapt'.", "Could it be adapt for a person in a wheelchair? :: Passive: be adapted.", "q"),
    T("Yes, of course. And the kitchen worktops are adjustable.", "Di que estupendo, y que si las obras son caras ajustarás tu presupuesto en consecuencia.", "Great. If the work is expensive, I'll adjust my budget accordingly.|Great. If the work is expensive, I'll adjust my budget accordingly.", "adjust ; budget ; accordingly",
      "Great. If the work is expensive, I'll adjust my budget according. :: The adverb is 'accordingly'.", "Great. If the work will be expensive, I'll adjust my budget accordingly. :: After 'if', use the present."),
    T("Very sensible. Would you like to see it this afternoon?", "Di que sí, por favor: ¡mejor que un piso en un rascacielos!", "Yes, please. It's better than a flat in a skyscraper!|Yes, please! It's better than a flat in a skyscraper.", "better than ; skyscraper",
      "Yes, please. It's better that a flat in a skyscraper! :: Comparatives use 'than'.", "Yes, please. It's more better than a flat in a skyscraper! :: 'Better' is already a comparative."),
  ], end: "Ha ha! I'll pick you up at three.",
  staff: [
    W("Saluda y pregunta qué tipo de casa busca.", "Good morning! What kind of house are you looking for?|What kind of house are you looking for?", "kind ; house ; looking for",
      "Good morning! What kind of house are you looking? :: We say 'look FOR'.", "Good morning! What kind of house you are looking for? :: Question order: are you looking…?", "q"),
    W("Ofrece una casita de campo preciosa con tejado de paja, aunque es un poco antigua.", "I've got a lovely cottage with a thatched roof. It's a bit old, though.|I have a lovely cottage with a thatched roof. It's a bit old, though.", "cottage ; thatched ; roof",
      "I've got a lovely cottage with a thatched ceiling. It's a bit old, though. :: The top outside part is the 'roof'.", "I've got a lovely cottage with a thatch roof. It's a bit old, though. :: The adjective is 'thatched'."),
    W("Di que claro, y que las encimeras de la cocina son regulables.", "Yes, of course. And the kitchen worktops are adjustable.|Of course. And the kitchen worktops are adjustable.", "kitchen ; adjustable",
      "Yes, of course. And the kitchen worktops are adjusted. :: Something you CAN adjust is 'adjustable'.", "Yes, of course. And the kitchen worktops is adjustable. :: Plural subject: are."),
    W("Di que es muy sensato y pregunta si quiere verla esta tarde.", "Very sensible. Would you like to see it this afternoon?|Very sensible. Would you like to see it this afternoon?", "sensible ; see it ; afternoon",
      "Very sensitive. Would you like to see it this afternoon? :: Showing good judgement = 'sensible'.", "Very sensible. Would you like to see it in this afternoon? :: 'This afternoon' (no 'in').", "q"),
    W("Ríete y di que la recogerás a las tres.", "Ha ha! I'll pick you up at three.|I'll pick you up at three.", "pick you up ; three",
      "Ha ha! I'll pick up you at three. :: With a pronoun: pick you up.", "Ha ha! I'll pick you up in three. :: Clock times: AT three."),
  ], bye: "Perfect. See you later!" });

