UNIT6({ unit: 28, name: "At the bakery", icon: "🥧", who: "Baker", face: "👩‍🍳", client: "Customer", cface: "🧑",
  turns: [
    T("Hello! What would you like today?", "Pide una tarta de manzana con masa por encima.", "I'd like an apple pie, please, with pastry on top.|An apple pie with pastry on top, please.", "apple pie ; pastry",
      "I'd like a apple pie, please, with pastry on top. :: Before a vowel sound: an apple pie.", "I'd like an apple pie, please, with paste on top. :: The dough for pies is 'pastry'."),
    T("Here you are. The inner layer is apple and cinnamon. Anything else?", "Pregunta cuántas capas tiene la lasaña.", "How many layers does the lasagne have?|How many layers has the lasagne got?", "layers ; lasagne/lasagna",
      "How many layers has the lasagne? :: Use 'does … have' or 'has … got'.", "How much layers does the lasagne have? :: Countable nouns: how many.", "q"),
    T("Five. Careful! Don't lean on the glass counter!", "Discúlpate: habrías jurado que era una pared.", "Sorry! I could have sworn it was a wall.|Oops, sorry! I could have sworn it was a wall.", "sworn ; wall",
      "Sorry! I could have swore it was a wall. :: The participle of swear is 'sworn'.", "Sorry! I could have sworn it is a wall. :: Keep the past: it was."),
    T("No problem. That counter is a curse, everybody leans on it!", "Jura que no lo volverás a hacer.", "I swear I won't do it again.|I swear I won't lean on it again.", "swear ; again",
      "I swear I don't do it again. :: A promise about the future: won't.", "I swear you I won't do it again. :: Say 'I swear' or 'I swear to you'."),
  ], end: "Ha ha! No need to take an oath. Enjoy your pie!",
  staff: [
    W("Saluda y pregunta qué quiere hoy.", "Hello! What would you like today?|Hi! What would you like today?", "what ; like ; today",
      "Hello! What do you like today? :: To offer: What would you like?", "Hello! What would you like to today? :: No 'to': What would you like today?", "q"),
    W("Dale la tarta, explica que la capa interior es de manzana y canela, y pregunta si quiere algo más.", "Here you are. The inner layer is apple and cinnamon. Anything else?|The inner layer is apple and cinnamon. Anything else?", "inner ; layer ; anything else",
      "Here you are. The inside layer is apple and cinnamon. Anything else? :: The adjective is 'inner'.", "Here you are. The inner layer is apple and cinnamon. Something else? :: In questions: anything else.", "q"),
    W("Di que cinco, y avisa: que no se apoye en el mostrador de cristal.", "Five. Careful! Don't lean on the glass counter!|Five. Careful, don't lean on the glass counter!", "lean on ; counter",
      "Five. Careful! Don't lean in the glass counter! :: We say 'lean ON'.", "Five. Careful! Don't leaning on the glass counter! :: Imperative: Don't lean."),
    W("Di que no pasa nada: ese mostrador es una maldición, todo el mundo se apoya en él.", "No problem. That counter is a curse, everybody leans on it!|No problem. That counter is a curse. Everyone leans on it!", "curse ; leans",
      "No problem. That counter is a curse, everybody lean on it! :: 'Everybody' takes a singular verb: leans.", "No problem. That counter is a course, everybody leans on it! :: Something that causes trouble is a 'curse'."),
    W("Ríete: no hace falta que haga un juramento. Que disfrute de la tarta.", "Ha ha! No need to take an oath. Enjoy your pie!|No need to take an oath! Enjoy your pie.", "oath ; enjoy",
      "Ha ha! No need to make an oath. Enjoy your pie! :: We TAKE (or swear) an oath.", "Ha ha! No need to take an oath. Enjoy with your pie! :: 'Enjoy' has no preposition."),
  ], bye: "Thank you. Bye!" });

UNIT6({ unit: 29, name: "A parking permit", icon: "🅿️", who: "Town hall clerk", face: "👨‍💼", client: "Resident", cface: "👩",
  turns: [
    T("Good morning. How can I help you?", "Di que necesitas un permiso para aparcar delante de tu casa.", "I need a permit to park in front of my house.|I'd like a permit to park in front of my house.", "permit ; park ; front",
      "I need a permission to park in front of my house. :: The official document is a 'permit'.", "I need a permit to park in front my house. :: We say 'in front OF'."),
    T("Fill in this form, please. Parking isn't permitted there without one.", "Pregunta cuánto tardará, más o menos (at a rough estimate).", "At a rough estimate, how long will it take?|How long will it take, at a rough estimate?", "estimate ; how long",
      "At a rough estimate, how long it will take? :: Question order: will it take.", "At a rough estimate, how much will it take? :: For time: how long.", "q"),
    T("About two weeks. Oh, careful! Your bag is slipping.", "Da las gracias, pero di que la tienes bien agarrada.", "Thanks, but I've got a firm grip on it.|Thank you, but I have a firm grip on it.", "firm ; grip",
      "Thanks, but I've got a strong grab on it. :: Holding firmly is a 'grip'.", "Thanks, but I've got a firm grip in it. :: We say 'a grip ON'."),
    T("Good. Last week a dog grabbed a man's sandwich right here!", "Ríete: el perro aprovechó la oportunidad.", "Ha ha! The dog seized the opportunity.|Ha ha! That dog seized the opportunity!", "seized ; opportunity",
      "Ha ha! The dog seized of the opportunity. :: 'Seize' takes no 'of'.", "Ha ha! The dog seized the oportunity. :: Spelling: opportunity."),
  ], end: "Exactly! Here's your receipt. Your permit will arrive by post.",
  staff: [
    W("Saluda y pregunta cómo puedes ayudarla.", "Good morning. How can I help you?|Hello. How can I help you?", "how ; help",
      "Good morning. How can I help to you? :: 'Help you' (no 'to').", "Good morning. How I can help you? :: Question order: How can I…?", "q"),
    W("Pide que rellene este impreso: no se permite aparcar allí sin permiso.", "Fill in this form, please. Parking isn't permitted there without one.|Please fill in this form. Parking isn't permitted there without a permit.", "form ; permitted",
      "Fill in this form, please. Parking isn't permit there without one. :: Passive: isn't permitted.", "Fill this form, please. Parking isn't permitted there without one. :: We say 'fill IN a form'.", "p"),
    W("Di que unas dos semanas y avisa de que se le resbala el bolso.", "About two weeks. Oh, careful! Your bag is slipping.|About two weeks. Careful, your bag is slipping!", "weeks ; bag ; slipping",
      "About two weeks. Oh, careful! Your bag is sliping. :: Spelling: slipping.", "About two weeks. Oh, careful! Your bag slips. :: Happening now: is slipping."),
    W("Cuenta que la semana pasada un perro le quitó el bocadillo a un hombre justo aquí.", "Good. Last week a dog grabbed a man's sandwich right here!|Last week a dog grabbed a man's sandwich right here!", "dog ; grabbed ; sandwich",
      "Good. Last week a dog has grabbed a man's sandwich right here! :: With 'last week' use the past simple.", "Good. Last week a dog grabed a man's sandwich right here! :: Spelling: grabbed."),
    W("Di que exacto, dale el recibo y explica que el permiso le llegará por correo.", "Exactly! Here's your receipt. Your permit will arrive by post.|Here's your receipt. Your permit will arrive by post.", "receipt ; permit ; post",
      "Exactly! Here's your recipe. Your permit will arrive by post. :: Proof of payment is a 'receipt'.", "Exactly! Here's your receipt. Your permit will arrive for post. :: The means: BY post."),
  ], bye: "Great. Thank you!" });

UNIT6({ unit: 30, name: "Emergency plumber", icon: "🚰", who: "Plumber", face: "👷", client: "Homeowner", cface: "🧑",
  turns: [
    T("Hello, emergency plumbing service. What's the problem?", "Di que es una emergencia: sale agua sucia de la alcantarilla.", "It's an emergency! Dirty water is coming up from the sewer.|It's an emergency. Dirty water is coming up from the sewer!", "emergency ; sewer",
      "It's a emergency! Dirty water is coming up from the sewer. :: Before a vowel sound: an emergency.", "It's an emergency! Dirty water is coming up from the sewage. :: The pipe is the 'sewer'; 'sewage' is the waste."),
    T("I'll be there in twenty minutes. Don't drink the tap water.", "Pregunta si el agua podría estar contaminada.", "Could the water be contaminated?|Could the tap water be contaminated?", "contaminated",
      "Could the water be contaminate? :: Passive: be contaminated.", "Could be the water contaminated? :: Question order: Could the water be…?", "q"),
    T("Yes, it could. And look, there's a rat. Rodents love sewers.", "Pregunta si deberías instalar un filtro en el grifo de la cocina.", "Should I install a filter on the kitchen tap?|Should I put a filter on the kitchen tap?", "filter ; tap",
      "Should I installing a filter on the kitchen tap? :: After 'should', base verb: install.", "Should I to install a filter on the kitchen tap? :: After 'should' no 'to'.", "q"),
    T("Good idea. I'll change the old pipes too.", "Pide que se deshaga también de la basura del sótano.", "Could you dispose of the rubbish in the basement too?|Could you also dispose of the rubbish in the basement?", "dispose of ; rubbish/garbage",
      "Could you dispose the rubbish in the basement too? :: We say 'dispose OF'.", "Could you dispose of the rubbishes in the basement too? :: 'Rubbish' is uncountable: no -es.", "p"),
  ], end: "Of course. Your house will be clean and safe by tonight.",
  staff: [
    W("Contesta: servicio de fontanería de urgencia. Pregunta cuál es el problema.", "Hello, emergency plumbing service. What's the problem?|Emergency plumbing service. What's the problem?", "emergency ; problem",
      "Hello, emergency plumbing service. Which is the problem? :: Ask 'What's the problem?'.", "Hello, emergence plumbing service. What's the problem? :: The noun is 'emergency'.", "q"),
    W("Di que llegarás en veinte minutos y que no beba agua del grifo.", "I'll be there in twenty minutes. Don't drink the tap water.|I'll be there in twenty minutes. Don't drink tap water.", "twenty minutes ; tap water",
      "I'll be there for twenty minutes. Don't drink the tap water. :: Time until you arrive: IN twenty minutes.", "I'll be there in twenty minutes. Not drink the tap water. :: Negative imperative: Don't drink."),
    W("Di que sí, podría, y señala una rata: a los roedores les encantan las alcantarillas.", "Yes, it could. And look, there's a rat. Rodents love sewers.|Yes, it could. Look, a rat! Rodents love sewers.", "rat ; rodents ; sewers",
      "Yes, it could. And look, there's a rat. Rodents loves sewers. :: Plural subject: love.", "Yes, it could. And look, there's a rat. Rodents love sewages. :: The pipes are 'sewers'."),
    W("Di que buena idea y que también cambiarás las tuberías viejas.", "Good idea. I'll change the old pipes too.|Good idea. I'll replace the old pipes too.", "change/replace ; pipes",
      "Good idea. I change the old pipes too. :: A decision now: I'll change.", "Good idea. I'll change the old pipes also too. :: Use 'too' at the end (not 'also too')."),
    W("Di que claro: la casa estará limpia y segura esta noche.", "Of course. Your house will be clean and safe by tonight.|Your house will be clean and safe by tonight.", "clean ; safe ; tonight",
      "Of course. Your house will be clean and safety by tonight. :: Use the adjective: safe.", "Of course. Your house will be clean and safe until tonight. :: A deadline: BY tonight."),
  ], bye: "Thank you so much!" });
